use std::net::{SocketAddr, UdpSocket, ToSocketAddrs};
use std::time::{Duration, Instant, SystemTime, UNIX_EPOCH};
use std::sync::{Arc, Mutex};
use std::thread;
use std::io::Write;

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let prog = args[0].clone();

    if args.len() < 2 {
        print_main_help(&prog);
        std::process::exit(2);
    }

    match args[1].as_str() {
        "server" => {
            let opts = parse_server_opts(&prog, &args[2..]);
            run_server(opts);
        }
        "client" => {
            let opts = parse_client_opts(&prog, &args[2..]);
            run_client(opts);
        }
        "help" => {
            if args.len() > 2 {
                match args[2].as_str() {
                    "server" => print_server_help(&prog, true),
                    "client" => print_client_help(&prog, true),
                    _ => print_main_help(&prog),
                }
            } else {
                print_main_help(&prog);
            }
        }
        "-h" | "--help" => {
            print_main_help(&prog);
        }
        arg => {
            eprintln!("error: unexpected argument '{}' found\n\nUsage: {} <COMMAND>\n\nFor more information, try '--help'.", arg, prog);
            std::process::exit(2);
        }
    }
}

fn print_main_help(prog: &str) {
    println!("Usage: {prog} <COMMAND>

Commands:
  server  Run as a perf server
  client  Run as a perf client
  help    Print this message or the help of the given subcommand(s)

Options:
  -h, --help  Print help");
}

// ============================================================
// CLI structures
// ============================================================

#[derive(Debug, Clone)]
struct CommonOpts {
    send_buffer_size: u64,
    recv_buffer_size: u64,
    conn_stats: bool,
    keylog: bool,
    initial_mtu: u64,
    no_protection: bool,
    initial_rtt: Option<u64>,
    ack_frequency: bool,
    congestion: Option<String>,
    stream_receive_window: Option<u64>,
    receive_window: Option<u64>,
    send_window: Option<u64>,
    max_udp_payload_size: u64,
    qlog_file: Option<String>,
}

impl Default for CommonOpts {
    fn default() -> Self {
        CommonOpts {
            send_buffer_size: 2 * 1024 * 1024,
            recv_buffer_size: 2 * 1024 * 1024,
            conn_stats: false,
            keylog: false,
            initial_mtu: 1200,
            no_protection: false,
            initial_rtt: None,
            ack_frequency: false,
            congestion: None,
            stream_receive_window: None,
            receive_window: None,
            send_window: None,
            max_udp_payload_size: 1472,
            qlog_file: None,
        }
    }
}

#[derive(Debug, Clone)]
struct ServerOpts {
    listen: SocketAddr,
    key: Option<String>,
    cert: Option<String>,
    common: CommonOpts,
}

#[derive(Debug, Clone)]
struct ClientOpts {
    host: String,
    ip: Option<String>,
    local_addr: Option<SocketAddr>,
    uni_requests: u64,
    bi_requests: u64,
    download_size: u64,
    upload_size: u64,
    duration: u64,
    interval: u64,
    json: Option<String>,
    common: CommonOpts,
}

// ============================================================
// SI suffix parsing (M = 1MiB, G = 1GiB)
// ============================================================

fn parse_size(s: &str) -> Result<u64, String> {
    if s.ends_with('M') {
        let n: u64 = s[..s.len()-1].parse().map_err(|e: std::num::ParseIntError| e.to_string())?;
        Ok(n * 1024 * 1024)
    } else if s.ends_with('G') {
        let n: u64 = s[..s.len()-1].parse().map_err(|e: std::num::ParseIntError| e.to_string())?;
        Ok(n * 1024 * 1024 * 1024)
    } else {
        s.parse::<u64>().map_err(|e| e.to_string())
    }
}

// ============================================================
// Argument parsing helpers
// ============================================================

struct ArgParser<'a> {
    args: &'a [String],
    pos: usize,
}

impl<'a> ArgParser<'a> {
    fn new(args: &'a [String]) -> Self {
        ArgParser { args, pos: 0 }
    }

    fn next_val(&mut self, flag: &str, prog: &str) -> String {
        if self.pos < self.args.len() {
            let val = self.args[self.pos].clone();
            self.pos += 1;
            val
        } else {
            eprintln!("error: a value is required for '{}' but none was supplied\n\nFor more information, try '--help'.", flag);
            std::process::exit(2);
        }
    }
}

fn parse_common_opts(args: &[String], prog: &str, _is_server: bool) -> (CommonOpts, Vec<(usize, String)>) {
    let mut opts = CommonOpts::default();
    let mut remaining = Vec::new();
    let mut i = 0;

    while i < args.len() {
        match args[i].as_str() {
            "--send-buffer-size" => {
                i += 1;
                if i >= args.len() { arg_missing("--send-buffer-size", prog); }
                let v = &args[i];
                opts.send_buffer_size = parse_size(v).unwrap_or_else(|e| {
                    eprintln!("error: invalid value '{}' for '--send-buffer-size <SEND_BUFFER_SIZE>': {}\n\nFor more information, try '--help'.", v, e);
                    std::process::exit(2);
                });
            }
            "--recv-buffer-size" => {
                i += 1;
                if i >= args.len() { arg_missing("--recv-buffer-size", prog); }
                let v = &args[i];
                opts.recv_buffer_size = parse_size(v).unwrap_or_else(|e| {
                    eprintln!("error: invalid value '{}' for '--recv-buffer-size <RECV_BUFFER_SIZE>': {}\n\nFor more information, try '--help'.", v, e);
                    std::process::exit(2);
                });
            }
            "--conn-stats" => { opts.conn_stats = true; }
            "--keylog" => { opts.keylog = true; }
            "--initial-mtu" => {
                i += 1;
                if i >= args.len() { arg_missing("--initial-mtu", prog); }
                let v = &args[i];
                opts.initial_mtu = v.parse().unwrap_or_else(|e: std::num::ParseIntError| {
                    eprintln!("error: invalid value '{}' for '--initial-mtu <INITIAL_MTU>': {}\n\nFor more information, try '--help'.", v, e);
                    std::process::exit(2);
                });
            }
            "--no-protection" => { opts.no_protection = true; }
            "--initial-rtt" => {
                i += 1;
                if i >= args.len() { arg_missing("--initial-rtt", prog); }
                let v = &args[i];
                let n: u64 = v.parse().unwrap_or_else(|e: std::num::ParseIntError| {
                    eprintln!("error: invalid value '{}' for '--initial-rtt <INITIAL_RTT>': {}\n\nFor more information, try '--help'.", v, e);
                    std::process::exit(2);
                });
                opts.initial_rtt = Some(n);
            }
            "--ack-frequency" => { opts.ack_frequency = true; }
            "--congestion" => {
                i += 1;
                if i >= args.len() { arg_missing("--congestion", prog); }
                let v = &args[i];
                match v.as_str() {
                    "cubic" | "bbr" | "new-reno" => { opts.congestion = Some(v.clone()); }
                    _ => {
                        eprintln!("error: invalid value '{}' for '--congestion <CONG_ALG>'\n  [possible values: cubic, bbr, new-reno]\n\nFor more information, try '--help'.", v);
                        std::process::exit(2);
                    }
                }
            }
            "--stream-receive-window" => {
                i += 1;
                if i >= args.len() { arg_missing("--stream-receive-window", prog); }
                let v = &args[i];
                opts.stream_receive_window = Some(parse_size(v).unwrap_or_else(|e| {
                    eprintln!("error: invalid value '{}' for '--stream-receive-window <STREAM_RECEIVE_WINDOW>': {}\n\nFor more information, try '--help'.", v, e);
                    std::process::exit(2);
                }));
            }
            "--receive-window" => {
                i += 1;
                if i >= args.len() { arg_missing("--receive-window", prog); }
                let v = &args[i];
                opts.receive_window = Some(parse_size(v).unwrap_or_else(|e| {
                    eprintln!("error: invalid value '{}' for '--receive-window <RECEIVE_WINDOW>': {}\n\nFor more information, try '--help'.", v, e);
                    std::process::exit(2);
                }));
            }
            "--send-window" => {
                i += 1;
                if i >= args.len() { arg_missing("--send-window", prog); }
                let v = &args[i];
                opts.send_window = Some(parse_size(v).unwrap_or_else(|e| {
                    eprintln!("error: invalid value '{}' for '--send-window <SEND_WINDOW>': {}\n\nFor more information, try '--help'.", v, e);
                    std::process::exit(2);
                }));
            }
            "--max-udp-payload-size" => {
                i += 1;
                if i >= args.len() { arg_missing("--max-udp-payload-size", prog); }
                let v = &args[i];
                opts.max_udp_payload_size = v.parse().unwrap_or_else(|e: std::num::ParseIntError| {
