    send_buffer_size: u64,
    recv_buffer_size: u64,
    conn_stats: bool,
    keylog: bool,
    initial_mtu: u64,
    no_protection: bool,
    initial_rtt: Option<u64>,
    ack_frequency: bool,
    congestion: Option<String>,
    stream_receive_window: Option<u64>,
    receive_window: Option<u64>,
    send_window: Option<u64>,
    max_udp_payload_size: u64,
    qlog_file: Option<String>,
}

impl Default for CommonOpts {
    fn default() -> Self {
        CommonOpts {
            send_buffer_size: 2 * 1024 * 1024,
            recv_buffer_size: 2 * 1024 * 1024,
            conn_stats: false,
            keylog: false,
            initial_mtu: 1200,
            no_protection: false,
            initial_rtt: None,
            ack_frequency: false,
            congestion: None,
            stream_receive_window: None,
            receive_window: None,
            send_window: None,
            max_udp_payload_size: 1472,
            qlog_file: None,
        }
    }
}

#[derive(Debug, Clone)]
struct ServerOpts {
    listen: SocketAddr,
    key: Option<String>,
    cert: Option<String>,
    common: CommonOpts,
}

#[derive(Debug, Clone)]
struct ClientOpts {
    host: String,
    ip: Option<String>,
    local_addr: Option<SocketAddr>,
    uni_requests: u64,
    bi_requests: u64,
    download_size: u64,
    upload_size: u64,
    duration: u64,
    interval: u64,
    json: Option<String>,
    common: CommonOpts,
}

// ============================================================
// SI suffix parsing (M = 1MiB, G = 1GiB)
// ============================================================

fn parse_size(s: &str) -> Result<u64, String> {
    if s.ends_with('M') {
        let n: u64 = s[..s.len()-1].parse().map_err(|e: std::num::ParseIntError| e.to_string())?;
        Ok(n * 1024 * 1024)
    } else if s.ends_with('G') {
        let n: u64 = s[..s.len()-1].parse().map_err(|e: std::num::ParseIntError| e.to_string())?;
        Ok(n * 1024 * 1024 * 1024)
    } else {
        s.parse::<u64>().map_err(|e| e.to_string())
    }
}

// ============================================================
// Argument parsing helpers
// ============================================================

struct ArgParser<'a> {
    args: &'a [String],
    pos: usize,
}

impl<'a> ArgParser<'a> {
    fn new(args: &'a [String]) -> Self {
        ArgParser { args, pos: 0 }
    }

    fn next_val(&mut self, flag: &str, prog: &str) -> String {
        if self.pos < self.args.len() {
            let val = self.args[self.pos].clone();
            self.pos += 1;
            val
        } else {
            eprintln!("error: a value is required for '{}' but none was supplied\n\nFor more information, try '--help'.", flag);
            std::process::exit(2);
        }
    }
}

fn parse_common_opts(args: &[String], prog: &str, _is_server: bool) -> (CommonOpts, Vec<(usize, String)>) {
    let mut opts = CommonOpts::default();
    let mut remaining = Vec::new();
    let mut i = 0;

    while i < args.len() {
        match args[i].as_str() {
            "--send-buffer-size" => {
                i += 1;
                if i >= args.len() { arg_missing("--send-buffer-size", prog); }
                let v = &args[i];
                opts.send_buffer_size = parse_size(v).unwrap_or_else(|e| {
                    eprintln!("error: invalid value '{}' for '--send-buffer-size <SEND_BUFFER_SIZE>': {}\n\nFor more information, try '--help'.", v, e);
                    std::process::exit(2);
                });
            }
            "--recv-buffer-size" => {
                i += 1;
                if i >= args.len() { arg_missing("--recv-buffer-size", prog); }
                let v = &args[i];
                opts.recv_buffer_size = parse_size(v).unwrap_or_else(|e| {
                    eprintln!("error: invalid value '{}' for '--recv-buffer-size <RECV_BUFFER_SIZE>': {}\n\nFor more information, try '--help'.", v, e);
                    std::process::exit(2);
                });
            }
            "--conn-stats" => { opts.conn_stats = true; }
            "--keylog" => { opts.keylog = true; }
            "--initial-mtu" => {
                i += 1;
                if i >= args.len() { arg_missing("--initial-mtu", prog); }
                let v = &args[i];
                opts.initial_mtu = v.parse().unwrap_or_else(|e: std::num::ParseIntError| {
                    eprintln!("error: invalid value '{}' for '--initial-mtu <INITIAL_MTU>': {}\n\nFor more information, try '--help'.", v, e);
                    std::process::exit(2);
                });
            }
            "--no-protection" => { opts.no_protection = true; }
            "--initial-rtt" => {
                i += 1;
                if i >= args.len() { arg_missing("--initial-rtt", prog); }
                let v = &args[i];
                let n: u64 = v.parse().unwrap_or_else(|e: std::num::ParseIntError| {
                    eprintln!("error: invalid value '{}' for '--initial-rtt <INITIAL_RTT>': {}\n\nFor more information, try '--help'.", v, e);
                    std::process::exit(2);
                });
                opts.initial_rtt = Some(n);
            }
            "--ack-frequency" => { opts.ack_frequency = true; }
            "--congestion" => {
                i += 1;
                if i >= args.len() { arg_missing("--congestion", prog); }
                let v = &args[i];
                match v.as_str() {
                    "cubic" | "bbr" | "new-reno" => { opts.congestion = Some(v.clone()); }
                    _ => {
                        eprintln!("error: invalid value '{}' for '--congestion <CONG_ALG>'\n  [possible values: cubic, bbr, new-reno]\n\nFor more information, try '--help'.", v);
                        std::process::exit(2);
                    }
                }
            }
            "--stream-receive-window" => {
                i += 1;
                if i >= args.len() { arg_missing("--stream-receive-window", prog); }
                let v = &args[i];
                opts.stream_receive_window = Some(parse_size(v).unwrap_or_else(|e| {
                    eprintln!("error: invalid value '{}' for '--stream-receive-window <STREAM_RECEIVE_WINDOW>': {}\n\nFor more information, try '--help'.", v, e);
                    std::process::exit(2);
                }));
            }
            "--receive-window" => {
                i += 1;
                if i >= args.len() { arg_missing("--receive-window", prog); }
                let v = &args[i];
                opts.receive_window = Some(parse_size(v).unwrap_or_else(|e| {
                    eprintln!("error: invalid value '{}' for '--receive-window <RECEIVE_WINDOW>': {}\n\nFor more information, try '--help'.", v, e);
                    std::process::exit(2);
                }));
            }
            "--send-window" => {
                i += 1;
                if i >= args.len() { arg_missing("--send-window", prog); }
                let v = &args[i];
                opts.send_window = Some(parse_size(v).unwrap_or_else(|e| {
                    eprintln!("error: invalid value '{}' for '--send-window <SEND_WINDOW>': {}\n\nFor more information, try '--help'.", v, e);
                    std::process::exit(2);
                }));
            }
            "--max-udp-payload-size" => {
                i += 1;
                if i >= args.len() { arg_missing("--max-udp-payload-size", prog); }
                let v = &args[i];
                opts.max_udp_payload_size = v.parse().unwrap_or_else(|e: std::num::ParseIntError| {
                    eprintln!("error: invalid value '{}' for '--max-udp-payload-size <MAX_UDP_PAYLOAD_SIZE>': {}\n\nFor more information, try '--help'.", v, e);
                    std::process::exit(2);
                });
            }
            "--qlog" => {
                i += 1;
                if i >= args.len() { arg_missing("--qlog", prog); }
                opts.qlog_file = Some(args[i].clone());
            }
            _ => {
                remaining.push((i, args[i].clone()));
            }
        }
        i += 1;
    }

    (opts, remaining)
}

fn arg_missing(flag: &str, prog: &str) -> ! {
    eprintln!("error: a value is required for '{}' but none was supplied\n\nFor more information, try '--help'.", flag);
    std::process::exit(2);
}

fn parse_server_opts(prog: &str, args: &[String]) -> ServerOpts {
    // Check for help first
    for arg in args {
        if arg == "-h" {
            print_server_help(prog, false);
            std::process::exit(0);
        }
        if arg == "--help" {
            print_server_help(prog, true);
            std::process::exit(0);
        }
    }

    let (mut common, remaining) = parse_common_opts(args, prog, true);

    let mut listen_str = "[::]:4433".to_string();
    let mut key: Option<String> = None;
    let mut cert: Option<String> = None;

    let mut i = 0;
    let remaining_args: Vec<_> = remaining.iter().map(|(_, s)| s.clone()).collect();

    while i < remaining_args.len() {
        match remaining_args[i].as_str() {
            "--listen" => {
                i += 1;
                if i >= remaining_args.len() { arg_missing("--listen", prog); }
                listen_str = remaining_args[i].clone();
            }
            "-k" | "--key" => {
                i += 1;
                if i >= remaining_args.len() { arg_missing("--key", prog); }
                key = Some(remaining_args[i].clone());
            }
            "-c" | "--cert" => {
                i += 1;
                if i >= remaining_args.len() { arg_missing("--cert", prog); }
                cert = Some(remaining_args[i].clone());
            }
            arg if arg.starts_with('-') => {
                eprintln!("error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\nUsage: {} server [OPTIONS]\n\nFor more information, try '--help'.", arg, arg, arg, prog);
                std::process::exit(2);
            }
            arg => {
                eprintln!("error: unexpected argument '{}' found\n\nUsage: {} server [OPTIONS]\n\nFor more information, try '--help'.", arg, prog);
                std::process::exit(2);
            }
        }
        i += 1;
    }

    let listen: SocketAddr = listen_str.parse().unwrap_or_else(|e| {
        eprintln!("error: invalid value '{}' for '--listen <LISTEN>': invalid socket address syntax\n\nFor more information, try '--help'.", listen_str);
        std::process::exit(2);
    });

    ServerOpts { listen, key, cert, common }
}

fn parse_client_opts(prog: &str, args: &[String]) -> ClientOpts {
    for arg in args {
        if arg == "-h" {
            print_client_help(prog, false);
            std::process::exit(0);
        }
        if arg == "--help" {
            print_client_help(prog, true);
            std::process::exit(0);
        }
    }

    let (common, remaining) = parse_common_opts(args, prog, false);

    let mut host = "localhost:4433".to_string();
    let mut ip: Option<String> = None;
    let mut local_addr: Option<SocketAddr> = None;
    let mut uni_requests: u64 = 0;
    let mut bi_requests: u64 = 1;
    let mut download_size: u64 = 1024 * 1024;
    let mut upload_size: u64 = 1024 * 1024;
    let mut duration: u64 = 60;
    let mut interval: u64 = 1;
    let mut json: Option<String> = None;

    let remaining_args: Vec<_> = remaining.iter().map(|(_, s)| s.clone()).collect();
    let mut positional_seen = false;
    let mut i = 0;

    while i < remaining_args.len() {
        match remaining_args[i].as_str() {
            "--ip" => {
                i += 1;
                if i >= remaining_args.len() { arg_missing("--ip", prog); }
                ip = Some(remaining_args[i].clone());
            }
            "--local-addr" => {
                i += 1;
                if i >= remaining_args.len() { arg_missing("--local-addr", prog); }
                let v = &remaining_args[i];
                local_addr = Some(v.parse().unwrap_or_else(|_| {
                    eprintln!("error: invalid value '{}' for '--local-addr <LOCAL_ADDR>': invalid socket address syntax\n\nFor more information, try '--help'.", v);
                    std::process::exit(2);
                }));
            }
            "--uni-requests" => {
                i += 1;
                if i >= remaining_args.len() { arg_missing("--uni-requests", prog); }
                let v = &remaining_args[i];
                uni_requests = v.parse().unwrap_or_else(|e: std::num::ParseIntError| {
                    eprintln!("error: invalid value '{}' for '--uni-requests <UNI_REQUESTS>': {}\n\nFor more information, try '--help'.", v, e);
                    std::process::exit(2);
                });
            }
            "--bi-requests" => {
                i += 1;
                if i >= remaining_args.len() { arg_missing("--bi-requests", prog); }
                let v = &remaining_args[i];
                bi_requests = v.parse().unwrap_or_else(|e: std::num::ParseIntError| {
                    eprintln!("error: invalid value '{}' for '--bi-requests <BI_REQUESTS>': {}\n\nFor more information, try '--help'.", v, e);
                    std::process::exit(2);
                });
            }
            "--download-size" => {
                i += 1;
                if i >= remaining_args.len() { arg_missing("--download-size", prog); }
                let v = &remaining_args[i];
                download_size = parse_size(v).unwrap_or_else(|e| {
                    eprintln!("error: invalid value '{}' for '--download-size <DOWNLOAD_SIZE>': {}\n\nFor more information, try '--help'.", v, e);
                    std::process::exit(2);
                });
            }
            "--upload-size" => {
                i += 1;
                if i >= remaining_args.len() { arg_missing("--upload-size", prog); }
                let v = &remaining_args[i];
                upload_size = parse_size(v).unwrap_or_else(|e| {
                    eprintln!("error: invalid value '{}' for '--upload-size <UPLOAD_SIZE>': {}\n\nFor more information, try '--help'.", v, e);
                    std::process::exit(2);
                });
            }
            "--duration" => {
                i += 1;
                if i >= remaining_args.len() { arg_missing("--duration", prog); }
                let v = &remaining_args[i];
                duration = v.parse().unwrap_or_else(|e: std::num::ParseIntError| {
                    eprintln!("error: invalid value '{}' for '--duration <DURATION>': {}\n\nFor more information, try '--help'.", v, e);
                    std::process::exit(2);
                });
            }
            "--interval" => {
                i += 1;
                if i >= remaining_args.len() { arg_missing("--interval", prog); }
                let v = &remaining_args[i];
                interval = v.parse().unwrap_or_else(|e: std::num::ParseIntError| {
                    eprintln!("error: invalid value '{}' for '--interval <INTERVAL>': {}\n\nFor more information, try '--help'.", v, e);
                    std::process::exit(2);
                });
            }
            "--json" => {
                i += 1;
                if i >= remaining_args.len() { arg_missing("--json", prog); }
                json = Some(remaining_args[i].clone());
            }
            arg if arg.starts_with('-') => {
                eprintln!("error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\nUsage: {} client [OPTIONS] [HOST]\n\nFor more information, try '--help'.", arg, arg, arg, prog);
                std::process::exit(2);
            }
            arg => {
                if positional_seen {
                    eprintln!("error: unexpected argument '{}' found\n\nUsage: {} client [OPTIONS] [HOST]\n\nFor more information, try '--help'.", arg, prog);
                    std::process::exit(2);
                }
                host = arg.to_string();
                positional_seen = true;
            }
        }
        i += 1;
    }

    ClientOpts { host, ip, local_addr, uni_requests, bi_requests, download_size, upload_size, duration, interval, json, common }
}

