// ============================================================
// Logging
// ============================================================

fn log_timestamp() -> String {
    let now = SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default();
    let secs = now.as_secs();
    let micros = now.subsec_micros();

    // Convert Unix timestamp to datetime
    let dt = unix_to_datetime(secs);
    format!("{:04}-{:02}-{:02}T{:02}:{:02}:{:02}.{:06}Z",
        dt.0, dt.1, dt.2, dt.3, dt.4, dt.5, micros)
}

// Returns (year, month, day, hour, min, sec)
fn unix_to_datetime(secs: u64) -> (u64, u64, u64, u64, u64, u64) {
    let sec_of_day = secs % 86400;
    let days = secs / 86400;

    let hour = sec_of_day / 3600;
    let min = (sec_of_day % 3600) / 60;
    let sec = sec_of_day % 60;

    // Days since 1970-01-01
    let mut year = 1970u64;
    let mut remaining_days = days;

    loop {
        let days_in_year = if is_leap(year) { 366 } else { 365 };
        if remaining_days < days_in_year { break; }
        remaining_days -= days_in_year;
        year += 1;
    }

    let months = [31u64, if is_leap(year) {29} else {28}, 31,30,31,30,31,31,30,31,30,31];
    let mut month = 1u64;
    for &m in &months {
        if remaining_days < m { break; }
        remaining_days -= m;
        month += 1;
    }

    (year, month, remaining_days + 1, hour, min, sec)
}

fn is_leap(year: u64) -> bool {
    (year % 4 == 0 && year % 100 != 0) || year % 400 == 0
}

macro_rules! log_warn {
    ($module:expr, $($arg:tt)*) => {
        println!("\x1b[2m{}\x1b[0m \x1b[33m WARN\x1b[0m \x1b[2m{}\x1b[0m\x1b[2m:\x1b[0m {}",
            log_timestamp(), $module, format!($($arg)*));
    }
}

macro_rules! log_error {
    ($module:expr, $($arg:tt)*) => {
        println!("\x1b[2m{}\x1b[0m \x1b[31mERROR\x1b[0m \x1b[2m{}\x1b[0m\x1b[2m:\x1b[0m {}",
            log_timestamp(), $module, format!($($arg)*));
    }
}

// ============================================================
// Socket buffer setup
// ============================================================

fn set_socket_buffers(sock: &UdpSocket, send_size: u64, recv_size: u64) {
    use std::os::unix::io::AsRawFd;

    let fd = sock.as_raw_fd();

    // Set send buffer
    let desired_send = send_size as i32;
    let ret = unsafe {
        libc_setsockopt(fd, 1, 7, desired_send) // SO_SNDBUF = 7
    };
    let actual_send = unsafe { libc_getsockopt(fd, 1, 7) };
    if actual_send < desired_send {
        log_warn!("perf", "Unable to set desired send buffer size. Desired: {}, Actual: {}", desired_send, actual_send);
    }

    // Set recv buffer
    let desired_recv = recv_size as i32;
    let ret2 = unsafe {
        libc_setsockopt(fd, 1, 8, desired_recv) // SO_RCVBUF = 8
    };
    let actual_recv = unsafe { libc_getsockopt(fd, 1, 8) };
    if actual_recv < desired_recv {
        log_warn!("perf", "Unable to set desired recv buffer size. Desired: {}, Actual: {}", desired_recv, actual_recv);
    }
}

unsafe fn libc_setsockopt(fd: i32, level: i32, optname: i32, val: i32) -> i32 {
    let val_ptr = &val as *const i32;
    libc_syscall_setsockopt(fd, level, optname, val_ptr as *const _, std::mem::size_of::<i32>() as u32)
}

unsafe fn libc_syscall_setsockopt(fd: i32, level: i32, optname: i32, optval: *const std::ffi::c_void, optlen: u32) -> i32 {
    let ret: i64;
    std::arch::asm!(
        "syscall",
        in("rax") 54i64, // SYS_setsockopt
        in("rdi") fd as i64,
        in("rsi") level as i64,
        in("rdx") optname as i64,
        in("r10") optval as i64,
        in("r8") optlen as i64,
        lateout("rax") ret,
        out("rcx") _,
        out("r11") _,
        options(nostack),
    );
    ret as i32
}

unsafe fn libc_getsockopt(fd: i32, level: i32, optname: i32) -> i32 {
    let mut val: i32 = 0;
    let mut len: u32 = std::mem::size_of::<i32>() as u32;
    let val_ptr = &mut val as *mut i32;
    let len_ptr = &mut len as *mut u32;

    let ret: i64;
    std::arch::asm!(
        "syscall",
        in("rax") 55i64, // SYS_getsockopt
        in("rdi") fd as i64,
        in("rsi") level as i64,
        in("rdx") optname as i64,
        in("r10") val_ptr as i64,
        in("r8") len_ptr as i64,
        lateout("rax") ret,
        out("rcx") _,
        out("r11") _,
        options(nostack),
    );
    val
}

