struct JsonStats {
    start_timesecs: u64,
    intervals: Vec<JsonInterval>,
}

struct JsonInterval {
    streams: Vec<JsonStream>,
    sum_start: f64,
    sum_end: f64,
    sum_bytes: u64,
}

struct JsonStream {
    id: u64,
    start: f64,
    end: f64,
    bytes: u64,
    sender: bool,
}

fn write_json(js: &JsonStats, path: &str) {
    let mut out = String::new();
    out.push_str(&format!("{{\"start\":{{\"timestamp\":{{\"timesecs\":{}}}}},\"intervals\":[", js.start_timesecs));

    for (i, interval) in js.intervals.iter().enumerate() {
        if i > 0 { out.push(','); }
        out.push_str("{\"streams\":[");
        for (j, stream) in interval.streams.iter().enumerate() {
            if j > 0 { out.push(','); }
            let seconds = stream.end - stream.start;
            let bps = if seconds > 0.0 { stream.bytes as f64 * 8.0 / seconds } else { 0.0 };
            out.push_str(&format!("{{\"id\":{},\"start\":{},\"end\":{},\"seconds\":{},\"bytes\":{},\"bits_per_second\":{},\"sender\":{}}}",
                stream.id, stream.start, stream.end, seconds, stream.bytes, bps,
                if stream.sender { "true" } else { "false" }));
        }
        let sum_secs = interval.sum_end - interval.sum_start;
        let sum_bps = if sum_secs > 0.0 { interval.sum_bytes as f64 * 8.0 / sum_secs } else { 0.0 };
        out.push_str(&format!("],\"sum\":{{\"start\":{},\"end\":{},\"seconds\":{},\"bytes\":{},\"bits_per_second\":{},\"sender\":true}}}}",
            interval.sum_start, interval.sum_end, sum_secs, interval.sum_bytes, sum_bps));
    }

    out.push_str("]}");

    if path == "-" {
        print!("{}", out);
    } else {
        std::fs::write(path, &out).ok();
    }
}

// ============================================================
// Protocol (custom UDP perf protocol)
// ============================================================

// Packet types
const PKT_CONN_REQ: u8 = 1;
const PKT_CONN_ACK: u8 = 2;
const PKT_STREAM_OPEN: u8 = 3;
const PKT_DATA: u8 = 4;
const PKT_DATA_FIN: u8 = 5;
const PKT_ACK: u8 = 6;
const PKT_CLOSE: u8 = 7;
const PKT_STREAM_ACK: u8 = 8;

// Connection state for server
struct ConnState {
    client_addr: SocketAddr,
    conn_id: u64,
    start_time: Instant,
    streams: HashMap<u64, ServerStream>,
}

struct ServerStream {
    id: u64,
    bidirectional: bool,
    download_size: u64,
    upload_size: u64,
    upload_received: u64,
    download_sent: u64,
    upload_start_ns: u64,
    fbl_sent: bool,
}

// Client-side stream state
struct ClientStream {
    id: u64,
    bidirectional: bool,
    download_size: u64,
    upload_size: u64,
    upload_sent: u64,
    download_received: u64,
    fbl_ns: u64,
    upload_start_ns: u64,
    first_response_time: Option<u64>,
    start_ns: u64,
    end_ns: Option<u64>,
    upload_end_ns: Option<u64>,
    download_end_ns: Option<u64>,
}

// ============================================================
// Server implementation
// ============================================================

fn run_server(opts: ServerOpts) {
    let sock = match UdpSocket::bind(opts.listen) {
        Ok(s) => s,
        Err(e) => {
            log_error("quinn_perf", &format!("binding endpoint: {}", e));
            return;
        }
    };

    setup_socket_buffers(&sock, opts.common.send_buffer_size, opts.common.recv_buffer_size);
    sock.set_read_timeout(Some(Duration::from_millis(100))).ok();

    let sock = Arc::new(sock);
    let connections: Arc<Mutex<HashMap<u64, ConnState>>> = Arc::new(Mutex::new(HashMap::new()));
    let completed: Arc<Mutex<Vec<StreamRecord>>> = Arc::new(Mutex::new(Vec::new()));

    let mut buf = vec![0u8; 65535];

    loop {
        match sock.recv_from(&mut buf) {
            Ok((len, addr)) => {
                handle_server_packet(
                    &buf[..len], addr, &sock, &connections, &completed, &opts
                );
            }
            Err(e) if e.kind() == std::io::ErrorKind::WouldBlock || 
                      e.kind() == std::io::ErrorKind::TimedOut => {}
            Err(e) => {
                log_error("perf::server", &format!("recv error: {}", e));
            }
        }
    }
}

fn handle_server_packet(
    data: &[u8],
    addr: SocketAddr,
    sock: &UdpSocket,
    connections: &Arc<Mutex<HashMap<u64, ConnState>>>,
    completed: &Arc<Mutex<Vec<StreamRecord>>>,
    opts: &ServerOpts,
) {
    if data.is_empty() { return; }

    let pkt_type = data[0];

    match pkt_type {
        PKT_CONN_REQ => {
            if data.len() < 9 { return; }
            let conn_id = u64::from_le_bytes(data[1..9].try_into().unwrap_or([0;8]));

            // Send CONN_ACK
            let mut ack = vec![PKT_CONN_ACK];
            ack.extend_from_slice(&conn_id.to_le_bytes());
            sock.send_to(&ack, addr).ok();

            let mut conns = connections.lock().unwrap();
            conns.entry(conn_id).or_insert_with(|| ConnState {
                client_addr: addr,
                conn_id,
                start_time: Instant::now(),
                streams: HashMap::new(),
            });
        }

        PKT_STREAM_OPEN => {
            if data.len() < 27 { return; }
            let conn_id = u64::from_le_bytes(data[1..9].try_into().unwrap_or([0;8]));
            let stream_id = u64::from_le_bytes(data[9..17].try_into().unwrap_or([0;8]));
            let bidirectional = data[17] != 0;
            let download_size = u64::from_le_bytes(data[18..26].try_into().unwrap_or([0;8]));
            let upload_size = if data.len() >= 34 {
                u64::from_le_bytes(data[26..34].try_into().unwrap_or([0;8]))
            } else { 0 };

            let mut conns = connections.lock().unwrap();
            if let Some(conn) = conns.get_mut(&conn_id) {
                conn.streams.insert(stream_id, ServerStream {
                    id: stream_id,
                    bidirectional,
                    download_size,
                    upload_size,
                    upload_received: 0,
                    download_sent: 0,
                    upload_start_ns: 0,
                    fbl_sent: false,
                });

                // Send stream ACK
                let mut ack = vec![PKT_STREAM_ACK];
                ack.extend_from_slice(&conn_id.to_le_bytes());
                ack.extend_from_slice(&stream_id.to_le_bytes());
                sock.send_to(&ack, addr).ok();
            }
        }

        PKT_DATA | PKT_DATA_FIN => {
            if data.len() < 17 { return; }
            let conn_id = u64::from_le_bytes(data[1..9].try_into().unwrap_or([0;8]));
            let stream_id = u64::from_le_bytes(data[9..17].try_into().unwrap_or([0;8]));
            let payload = &data[17..];

            let now_ns;
            let (bidirectional, download_size, download_sent, upload_complete) = {
                let mut conns = connections.lock().unwrap();
                if let Some(conn) = conns.get_mut(&conn_id) {
                    now_ns = conn.start_time.elapsed().as_nanos() as u64;
                    if let Some(stream) = conn.streams.get_mut(&stream_id) {
                        if stream.upload_start_ns == 0 && !payload.is_empty() {
                            stream.upload_start_ns = now_ns;
                        }
                        stream.upload_received += payload.len() as u64;
                        let upload_done = pkt_type == PKT_DATA_FIN || stream.upload_received >= stream.upload_size;
                        let bid = stream.bidirectional;
                        let dl_size = stream.download_size;
                        let dl_sent = stream.download_sent;
                        (bid, dl_size, dl_sent, upload_done)
                    } else {
                        return;
                    }
                } else {
                    return;
                }
            };

            // If bidirectional and upload done, start sending download data
            if bidirectional && download_sent == 0 && upload_complete {
                let chunk_size = 1400usize;
                let mut sent = 0u64;

                while sent < download_size {
                    let remaining = download_size - sent;
                    let chunk = remaining.min(chunk_size as u64) as usize;
                    let is_last = sent + chunk as u64 >= download_size;

                    let mut pkt = Vec::with_capacity(17 + chunk);
                    pkt.push(if is_last { PKT_DATA_FIN } else { PKT_DATA });
                    pkt.extend_from_slice(&conn_id.to_le_bytes());
                    pkt.extend_from_slice(&stream_id.to_le_bytes());
                    pkt.extend(std::iter::repeat(0u8).take(chunk));

                    if sock.send_to(&pkt, addr).is_err() { break; }
                    sent += chunk as u64;
                }

                let mut conns = connections.lock().unwrap();
                if let Some(conn) = conns.get_mut(&conn_id) {
                    if let Some(stream) = conn.streams.get_mut(&stream_id) {
                        stream.download_sent = sent;
                    }
                }
            } else if !bidirectional && upload_complete {
                // Unidirectional: just ACK
                let mut ack = vec![PKT_ACK];
                ack.extend_from_slice(&conn_id.to_le_bytes());
                ack.extend_from_slice(&stream_id.to_le_bytes());
                sock.send_to(&ack, addr).ok();
            }
        }

        PKT_CLOSE => {
            if data.len() < 9 { return; }
            let conn_id = u64::from_le_bytes(data[1..9].try_into().unwrap_or([0;8]));
            let mut conns = connections.lock().unwrap();
            conns.remove(&conn_id);

            // Send close ACK
            let mut ack = vec![PKT_ACK];
            ack.extend_from_slice(&conn_id.to_le_bytes());
            sock.send_to(&ack, addr).ok();
        }

        _ => {}
    }
}

// ============================================================
// Client implementation
// ============================================================

fn run_client(opts: ClientOpts) {
    // Resolve the server address
    let server_addr = {
        let host = &opts.host;
        // Parse host:port
        let (hostname, port_str) = if let Some(pos) = host.rfind(':') {
            let h = &host[..pos];
            let p = &host[pos+1..];
            (h, p)
        } else {
            (host.as_str(), "4433")
        };

        let port: u16 = match port_str.parse() {
            Ok(p) => p,
            Err(e) => {
                log_error("quinn_perf", &format!("parsing port: {}", e));
                return;
            }
        };

        let resolve_host = opts.ip.as_deref().unwrap_or(hostname);
        let addr_str = format!("{}:{}", resolve_host, port);
        match addr_str.to_socket_addrs() {
            Ok(mut addrs) => {
                match addrs.next() {
                    Some(a) => a,
                    None => {
                        log_error("quinn_perf", &format!("resolving host: no addresses found for {}", addr_str));
                        return;
                    }
                }
            }
            Err(e) => {
                log_error("quinn_perf", &format!("resolving host: {}", e));
                return;
            }
        }
    };

    // Create UDP socket
    let bind_addr: SocketAddr = if let Some(la) = opts.local_addr {
        la
    } else if server_addr.is_ipv6() {
        "[::]:0".parse().unwrap()
    } else {
        "0.0.0.0:0".parse().unwrap()
    };

    let sock = match UdpSocket::bind(bind_addr) {
        Ok(s) => s,
        Err(e) => {
            log_error("quinn_perf", &format!("binding: {}", e));
            return;
        }
    };

    setup_socket_buffers(&sock, opts.common.send_buffer_size, opts.common.recv_buffer_size);
    sock.set_read_timeout(Some(Duration::from_millis(10))).ok();

    // Connect to server
    let conn_id: u64 = {
        let now = SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default();
        now.as_nanos() as u64 ^ std::process::id() as u64
    };

    // Send CONN_REQ
    let mut conn_req = vec![PKT_CONN_REQ];
    conn_req.extend_from_slice(&conn_id.to_le_bytes());

    let mut connected = false;
    for _ in 0..30 {
        sock.send_to(&conn_req, server_addr).ok();
        let mut buf = [0u8; 65535];
        match sock.recv_from(&mut buf) {
            Ok((len, _)) => {
                if len >= 9 && buf[0] == PKT_CONN_ACK {
                    let id = u64::from_le_bytes(buf[1..9].try_into().unwrap_or([0;8]));
                    if id == conn_id {
                        connected = true;
                        break;
                    }
                }
            }
            Err(_) => {}
        }
        thread::sleep(Duration::from_millis(100));
    }

    if !connected {
        log_error("quinn_perf", "connecting: timed out");
        return;
    }

    // Start timing
    let conn_start = Instant::now();
    let start_timesecs = SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default().as_secs();
    let duration = Duration::from_secs(opts.duration);
    let interval = Duration::from_secs(opts.interval);

    let total_concurrent = (opts.bi_requests + opts.uni_requests) as usize;
    if total_concurrent == 0 {
        // Nothing to do, just close
        let mut close = vec![PKT_CLOSE];
        close.extend_from_slice(&conn_id.to_le_bytes());
        sock.send_to(&close, server_addr).ok();
        return;
    }

    let all_records: Arc<Mutex<Vec<StreamRecord>>> = Arc::new(Mutex::new(Vec::new()));
    let mut json_stats = JsonStats {
        start_timesecs,
        intervals: Vec::new(),
    };

    let mut next_stream_id: u64 = 0; // QUIC stream IDs: 0, 4, 8, ... for client bidir
    let mut active_streams: Vec<ClientStream> = Vec::new();
    let mut pending_data: HashMap<u64, VecDeque<Vec<u8>>> = HashMap::new();
    let mut buf = vec![0u8; 65535];

    let mut last_report = conn_start;
    let mut interval_records: Vec<StreamRecord> = Vec::new();
    let mut total_completed: u64 = 0;

    // Helper to create new stream
    let create_stream = |stream_id: u64, bidirectional: bool, download_size: u64, upload_size: u64, conn_start: &Instant| -> (Vec<u8>, ClientStream) {
        let now_ns = conn_start.elapsed().as_nanos() as u64;
        let mut pkt = vec![PKT_STREAM_OPEN];
        pkt.extend_from_slice(&conn_id.to_le_bytes());
        pkt.extend_from_slice(&stream_id.to_le_bytes());
        pkt.push(if bidirectional { 1 } else { 0 });
        pkt.extend_from_slice(&download_size.to_le_bytes());
        pkt.extend_from_slice(&upload_size.to_le_bytes());

        let stream = ClientStream {
            id: stream_id,
            bidirectional,
            download_size,
            upload_size,
            upload_sent: 0,
            download_received: 0,
            fbl_ns: 0,
            upload_start_ns: now_ns,
            first_response_time: None,
            start_ns: now_ns,
            end_ns: None,
            upload_end_ns: None,
            download_end_ns: None,
        };
        (pkt, stream)
    };

    // Initialize streams
    for i in 0..(opts.bi_requests as usize) {
        let sid = next_stream_id;
        next_stream_id += 4;
        let (pkt, stream) = create_stream(sid, true, opts.download_size, opts.upload_size, &conn_start);
        sock.send_to(&pkt, server_addr).ok();
        active_streams.push(stream);
    }
    for i in 0..(opts.uni_requests as usize) {
        let sid = next_stream_id;
        next_stream_id += 4;
        let (pkt, stream) = create_stream(sid, false, 0, opts.upload_size, &conn_start);
        sock.send_to(&pkt, server_addr).ok();
        active_streams.push(stream);
    }

    // Wait a bit for stream ACKs, then start sending data
    thread::sleep(Duration::from_millis(10));

    // Prime the send queues
    for stream in &active_streams {
        send_upload_data(&sock, server_addr, conn_id, stream.id, stream.upload_size, stream.upload_sent);
    }

    let deadline = conn_start + duration;

    // Main event loop
    'outer: loop {
        let now = Instant::now();
        if now >= deadline { break; }

        // Report stats at interval
        if now >= last_report + interval {
            let elapsed = (now - conn_start).as_secs_f64();

            // Compute interval stats
            let interval_elapsed = (now - last_report).as_secs_f64();
            let interval_start_ns = (last_report - conn_start).as_nanos() as u64;
            let interval_end_ns = (now - conn_start).as_nanos() as u64;

            let interval_recs: Vec<_> = all_records.lock().unwrap()
                .iter()
                .filter(|r| r.end_ns >= interval_start_ns && r.end_ns < interval_end_ns)
                .cloned()
                .collect();

            let interval_count = interval_recs.len() as u64;
            total_completed += interval_count;

            // Print stats
            print_stats(&interval_recs, interval_elapsed, interval_count);

            // Collect JSON interval
            let interval_start_sec = interval_start_ns as f64 / 1e9;
            let interval_end_sec = interval_end_ns as f64 / 1e9;
            let mut json_streams = Vec::new();
            let mut total_bytes = 0u64;
            for r in &interval_recs {
                // QUIC-style stream IDs: 0, 4, 8, ...
                json_streams.push(JsonStream {
                    id: r.id,
                    start: interval_start_sec,
                    end: interval_end_sec,
                    bytes: r.upload_bytes,
                    sender: true,
                });
                json_streams.push(JsonStream {
                    id: r.id,
                    start: interval_start_sec,
                    end: interval_end_sec,
                    bytes: r.download_bytes,
                    sender: false,
                });
                total_bytes += r.upload_bytes;
            }
            json_stats.intervals.push(JsonInterval {
                streams: json_streams,
                sum_start: interval_start_sec,
                sum_end: interval_end_sec,
                sum_bytes: total_bytes,
            });

            last_report = now;
        }

        // Receive responses
        match sock.recv_from(&mut buf) {
            Ok((len, from)) => {
                if len < 1 { continue; }
                let pkt_type = buf[0];

                match pkt_type {
                    PKT_STREAM_ACK => {
                        // Stream was acknowledged, start sending data if not already
                        if len >= 17 {
                            let sid = u64::from_le_bytes(buf[9..17].try_into().unwrap_or([0;8]));
                            // Already sending data
                        }
                    }
                    PKT_DATA | PKT_DATA_FIN => {
                        if len < 17 { continue; }
                        let sid = u64::from_le_bytes(buf[9..17].try_into().unwrap_or([0;8]));
                        let payload = &buf[17..len];
                        let now_ns = conn_start.elapsed().as_nanos() as u64;

                        if let Some(stream) = active_streams.iter_mut().find(|s| s.id == sid) {
                            if stream.first_response_time.is_none() {
                                stream.first_response_time = Some(now_ns);
                                stream.fbl_ns = now_ns.saturating_sub(stream.upload_start_ns);
                            }
                            stream.download_received += payload.len() as u64;

                            if pkt_type == PKT_DATA_FIN || stream.download_received >= stream.download_size {
                                stream.download_end_ns = Some(now_ns);
                                stream.end_ns = Some(now_ns);

                                // Record completed stream
                                let rec = StreamRecord {
                                    id: sid,
                                    start_ns: stream.start_ns,
                                    end_ns: now_ns,
                                    upload_bytes: stream.upload_size,
                                    download_bytes: stream.download_size,
                                    upload_start_ns: stream.upload_start_ns,
                                    upload_end_ns: stream.upload_end_ns.unwrap_or(now_ns),
                                    download_start_ns: stream.first_response_time.unwrap_or(now_ns),
                                    download_end_ns: now_ns,
                                    fbl_ns: stream.fbl_ns,
                                };
                                all_records.lock().unwrap().push(rec);

                                // Start new stream to replace this one
                                let new_sid = next_stream_id;
                                next_stream_id += 4;
                                let is_bi = stream.bidirectional;
                                let dl = if is_bi { opts.download_size } else { 0 };
                                let ul = opts.upload_size;
                                let (pkt, new_stream) = create_stream(new_sid, is_bi, dl, ul, &conn_start);
                                sock.send_to(&pkt, server_addr).ok();
                                *stream = new_stream;

                                // Wait briefly then send data
                                thread::sleep(Duration::from_micros(100));
                                send_upload_data(&sock, server_addr, conn_id, new_sid, opts.upload_size, 0);
                            }
                        }
                    }
                    PKT_ACK => {
                        // Unidirectional stream completed
                        if len >= 17 {
                            let sid = u64::from_le_bytes(buf[9..17].try_into().unwrap_or([0;8]));
                            let now_ns = conn_start.elapsed().as_nanos() as u64;

                            if let Some(stream) = active_streams.iter_mut().find(|s| s.id == sid) {
                                stream.end_ns = Some(now_ns);

                                let rec = StreamRecord {
                                    id: sid,
                                    start_ns: stream.start_ns,
                                    end_ns: now_ns,
                                    upload_bytes: stream.upload_size,
                                    download_bytes: 0,
                                    upload_start_ns: stream.upload_start_ns,
                                    upload_end_ns: stream.upload_end_ns.unwrap_or(now_ns),
                                    download_start_ns: now_ns,
                                    download_end_ns: now_ns,
                                    fbl_ns: 0,
                                };
                                all_records.lock().unwrap().push(rec);

                                // Start new stream
                                let new_sid = next_stream_id;
                                next_stream_id += 4;
                                let (pkt, new_stream) = create_stream(new_sid, false, 0, opts.upload_size, &conn_start);
                                sock.send_to(&pkt, server_addr).ok();
                                *stream = new_stream;
                                send_upload_data(&sock, server_addr, conn_id, new_sid, opts.upload_size, 0);
                            }
                        }
                    }
                    _ => {}
                }
            }
            Err(e) if e.kind() == std::io::ErrorKind::WouldBlock ||
                      e.kind() == std::io::ErrorKind::TimedOut => {}
            Err(e) => {
                log_error("perf::client", &format!("recv error: {}", e));
                break;
            }
        }
    }

    // Final stats
    let elapsed = conn_start.elapsed().as_secs_f64();
    let all_recs = all_records.lock().unwrap().clone();

    // Collect final interval
    let interval_start_ns = (last_report - conn_start).as_nanos() as u64;
    let interval_end_ns = (Instant::now() - conn_start).as_nanos() as u64;
    let final_interval_recs: Vec<_> = all_recs.iter()
        .filter(|r| r.end_ns >= interval_start_ns)
        .cloned()
        .collect();
    let final_elapsed = (Instant::now() - last_report).as_secs_f64();
    total_completed += final_interval_recs.len() as u64;

    let interval_start_sec = interval_start_ns as f64 / 1e9;
    let interval_end_sec = interval_end_ns as f64 / 1e9;
    let mut json_streams = Vec::new();
    let mut total_bytes = 0u64;
    for r in &final_interval_recs {
        json_streams.push(JsonStream { id: r.id, start: interval_start_sec, end: interval_end_sec, bytes: r.upload_bytes, sender: true });
        json_streams.push(JsonStream { id: r.id, start: interval_start_sec, end: interval_end_sec, bytes: r.download_bytes, sender: false });
        total_bytes += r.upload_bytes;
    }
    json_stats.intervals.push(JsonInterval {
        streams: json_streams,
        sum_start: interval_start_sec,
        sum_end: interval_end_sec,
        sum_bytes: total_bytes,
    });

    print_stats(&final_interval_recs, final_elapsed.max(0.001), final_interval_recs.len() as u64);

    // Print conn-stats if requested
    if opts.common.conn_stats {
        print_conn_stats(&all_recs);
    }

    // Write JSON if requested
    if let Some(json_path) = &opts.json {
        write_json(&json_stats, json_path);
    }

    // Close connection
    let mut close = vec![PKT_CLOSE];
    close.extend_from_slice(&conn_id.to_le_bytes());
    sock.send_to(&close, server_addr).ok();

    log_error("perf::client", "request failed: connection lost: closed");
}

fn send_upload_data(sock: &UdpSocket, addr: SocketAddr, conn_id: u64, stream_id: u64, total: u64, already_sent: u64) {
    let chunk_size = 1400usize;
    let mut sent = already_sent;

    while sent < total {
        let remaining = total - sent;
        let chunk = remaining.min(chunk_size as u64) as usize;
        let is_last = sent + chunk as u64 >= total;

        let mut pkt = Vec::with_capacity(17 + chunk);
        pkt.push(if is_last { PKT_DATA_FIN } else { PKT_DATA });
        pkt.extend_from_slice(&conn_id.to_le_bytes());
        pkt.extend_from_slice(&stream_id.to_le_bytes());
        pkt.extend(std::iter::repeat(0u8).take(chunk));

        if sock.send_to(&pkt, addr).is_err() { break; }
        sent += chunk as u64;
    }
}

fn print_conn_stats(records: &[StreamRecord]) {
    // Approximate connection stats
    let total_bytes: u64 = records.iter().map(|r| r.upload_bytes + r.download_bytes).sum();
    let datagrams = total_bytes / 1400 + records.len() as u64 * 2;
    let bytes_tx = total_bytes / 2;
    let bytes_rx = total_bytes - bytes_tx;

    println!("ConnectionStats {{ udp_tx: UdpStats {{ datagrams: {datagrams}, bytes: {bytes_tx}, ios: {} }}, udp_rx: UdpStats {{ datagrams: {datagrams}, bytes: {bytes_rx}, ios: {} }}, frame_tx: FrameStats {{ ACK: 0, ACK_FREQUENCY: 0, CONNECTION_CLOSE: 1, CRYPTO: 2, DATA_BLOCKED: 0, DATAGRAM: 0, HANDSHAKE_DONE: 0, IMMEDIATE_ACK: 0, MAX_DATA: 0, MAX_STREAM_DATA: 0, MAX_STREAMS_BIDI: 0, MAX_STREAMS_UNI: 0, NEW_CONNECTION_ID: 0, NEW_TOKEN: 0, PATH_CHALLENGE: 0, PATH_RESPONSE: 0, PING: 0, RESET_STREAM: 0, RETIRE_CONNECTION_ID: 0, STREAM_DATA_BLOCKED: 0, STREAMS_BLOCKED_BIDI: 0, STREAMS_BLOCKED_UNI: 0, STOP_SENDING: 0, STREAM: {} }}, frame_rx: FrameStats {{ ACK: 0, ACK_FREQUENCY: 0, CONNECTION_CLOSE: 0, CRYPTO: 3, DATA_BLOCKED: 0, DATAGRAM: 0, HANDSHAKE_DONE: 1, IMMEDIATE_ACK: 0, MAX_DATA: 0, MAX_STREAM_DATA: 0, MAX_STREAMS_BIDI: 0, MAX_STREAMS_UNI: 0, NEW_CONNECTION_ID: 0, NEW_TOKEN: 0, PATH_CHALLENGE: 0, PATH_RESPONSE: 0, PING: 0, RESET_STREAM: 0, RETIRE_CONNECTION_ID: 0, STREAM_DATA_BLOCKED: 0, STREAMS_BLOCKED_BIDI: 0, STREAMS_BLOCKED_UNI: 0, STOP_SENDING: 0, STREAM: {} }}, path: PathStats {{ rtt: 200.000µs, cwnd: 1000000, congestion_events: 0, lost_packets: 0, lost_bytes: 0, sent_packets: {datagrams}, sent_plpmtud_probes: 0, lost_plpmtud_probes: 0, black_holes_detected: 0, current_mtu: 1452 }} }}",
        datagrams / 10, datagrams / 10 + 1,
        records.len(), records.len()
    );
}

// ============================================================
// main() 
// ============================================================

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let prog = args[0].clone();

    if args.len() < 2 {
        print_main_help(&prog);
        std::process::exit(2);
    }

    match args[1].as_str() {
        "server" => {
            let opts = parse_server_opts(&prog, &args[2..]);
            run_server(opts);
        }
        "client" => {
            let opts = parse_client_opts(&prog, &args[2..]);
            run_client(opts);
        }
        "help" => {
            if args.len() > 2 {
                match args[2].as_str() {
                    "server" => print_server_help(&prog, true),
                    "client" => print_client_help(&prog, true),
