// ============================================================
// libc FFI
// ============================================================
extern "C" {
    fn setsockopt(sockfd: i32, level: i32, optname: i32, optval: *const c_void, optlen: u32) -> i32;
    fn getsockopt(sockfd: i32, level: i32, optname: i32, optval: *mut c_void, optlen: *mut u32) -> i32;
}

const SOL_SOCKET: i32 = 1;
const SO_SNDBUF: i32 = 7;
const SO_RCVBUF: i32 = 8;

fn setsockopt_int(fd: i32, level: i32, optname: i32, val: i32) -> i32 {
    unsafe {
        setsockopt(fd, level, optname, &val as *const i32 as *const c_void, 4)
    }
}

fn getsockopt_int(fd: i32, level: i32, optname: i32) -> i32 {
    unsafe {
        let mut val: i32 = 0;
        let mut len: u32 = 4;
        getsockopt(fd, level, optname, &mut val as *mut i32 as *mut c_void, &mut len);
        val
    }
}

// ============================================================
