fn main() {
    let args: Vec<String> = std::env::args().collect();
    let prog = args[0].clone();

    if args.len() < 2 {
        print_main_help(&prog);
        std::process::exit(2);
    }

    match args[1].as_str() {
        "server" => {
            let opts = parse_server_opts(&prog, &args[2..]);
