fn format_duration_ns(ns: u64) -> String {
    if ns == 0 {
        "0.00ns".to_string()
    } else if ns < 1_000 {
        format!("{:.2}ns", ns as f64)
    } else if ns < 1_000_000 {
        format!("{:.2}\u{b5}s", ns as f64 / 1_000.0)
    } else if ns < 1_000_000_000 {
        format!("{:.2}ms", ns as f64 / 1_000_000.0)
    } else {
        format!("{:.2}s", ns as f64 / 1_000_000_000.0)
    }
}

fn format_throughput(bytes: u64, duration_ns: u64) -> String {
    if duration_ns == 0 {
        "0.00 Mb/s".to_string()
    } else {
        let bits_per_sec = bytes as f64 * 8.0 * 1_000_000_000.0 / duration_ns as f64;
        let mbps = bits_per_sec / 1_000_000.0;
        format!("{:.2} Mb/s", mbps)
    }
}

fn percentile(values: &mut Vec<u64>, p: f64) -> u64 {
    if values.is_empty() { return 0; }
    values.sort_unstable();
    let idx = ((p / 100.0) * (values.len() - 1) as f64).round() as usize;
    values[idx.min(values.len() - 1)]
}

fn print_stats(records: &[StreamRecord], elapsed_secs: f64, total_reqs: u64) {
    println!("Overall stats:");
    println!("RPS: {:.2} ({} requests in {:.2}s)", total_reqs as f64 / elapsed_secs, total_reqs, elapsed_secs);
    println!();
    println!("Stream metrics:");
    println!();

    // Collect data
    let mut upload_durations: Vec<u64> = records.iter().map(|r| r.upload_end_ns.saturating_sub(r.upload_start_ns)).collect();
    let mut download_durations: Vec<u64> = records.iter().map(|r| r.download_end_ns.saturating_sub(r.download_start_ns)).collect();
    let mut fbls: Vec<u64> = records.iter().map(|r| r.fbl_ns).collect();
    let mut upload_throughputs: Vec<f64> = records.iter().map(|r| {
        let d = r.upload_end_ns.saturating_sub(r.upload_start_ns);
        if d == 0 { 0.0 } else { r.upload_bytes as f64 * 8.0 * 1e9 / (d as f64 * 1e6) }
    }).collect();
    let mut download_throughputs: Vec<f64> = records.iter().map(|r| {
        let d = r.download_end_ns.saturating_sub(r.download_start_ns);
        if d == 0 { 0.0 } else { r.download_bytes as f64 * 8.0 * 1e9 / (d as f64 * 1e6) }
    }).collect();

    let n = records.len();
    if n == 0 { return; }

    // Compute percentiles
    let avg_upload = upload_durations.iter().sum::<u64>() / n as u64;
    let avg_download = download_durations.iter().sum::<u64>() / n as u64;
    let avg_fbl = fbls.iter().sum::<u64>() / n as u64;
    let avg_up_tp = upload_throughputs.iter().sum::<f64>() / n as f64;
    let avg_dn_tp = download_throughputs.iter().sum::<f64>() / n as f64;

    upload_durations.sort_unstable();
    download_durations.sort_unstable();
    fbls.sort_unstable();
    upload_throughputs.sort_unstable_by(|a, b| a.partial_cmp(b).unwrap());
    download_throughputs.sort_unstable_by(|a, b| a.partial_cmp(b).unwrap());

    let pct_idx = |p: f64, len: usize| -> usize {
        if len == 0 { return 0; }
        ((p / 100.0) * (len - 1) as f64).round() as usize
    };

    let p0_up = upload_durations[0];
    let p10_up = upload_durations[pct_idx(10.0, n)];
    let p50_up = upload_durations[pct_idx(50.0, n)];
    let p90_up = upload_durations[pct_idx(90.0, n)];
    let p100_up = upload_durations[n-1];

    let p0_dn = download_durations[0];
    let p10_dn = download_durations[pct_idx(10.0, n)];
    let p50_dn = download_durations[pct_idx(50.0, n)];
    let p90_dn = download_durations[pct_idx(90.0, n)];
    let p100_dn = download_durations[n-1];

    let p0_fbl = fbls[0];
    let p10_fbl = fbls[pct_idx(10.0, n)];
    let p50_fbl = fbls[pct_idx(50.0, n)];
    let p90_fbl = fbls[pct_idx(90.0, n)];
    let p100_fbl = fbls[n-1];

    let p0_up_tp = upload_throughputs[0];
    let p10_up_tp = upload_throughputs[pct_idx(10.0, n)];
    let p50_up_tp = upload_throughputs[pct_idx(50.0, n)];
    let p90_up_tp = upload_throughputs[pct_idx(90.0, n)];
    let p100_up_tp = upload_throughputs[n-1];

    let p0_dn_tp = download_throughputs[0];
    let p10_dn_tp = download_throughputs[pct_idx(10.0, n)];
    let p50_dn_tp = download_throughputs[pct_idx(50.0, n)];
    let p90_dn_tp = download_throughputs[pct_idx(90.0, n)];
    let p100_dn_tp = download_throughputs[n-1];

    // Print table header
    println!("      \u{2502} Upload Duration \u{2502} Download Duration | FBL        | Upload Throughput | Download Throughput");
    println!("\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{253c}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{253c}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{253c}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{253c}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{253c}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}");

    print_row("AVG ", avg_upload, avg_download, avg_fbl, avg_up_tp, avg_dn_tp);
    print_row("P0  ", p0_up, p0_dn, p0_fbl, p0_up_tp, p0_dn_tp);
    print_row("P10 ", p10_up, p10_dn, p10_fbl, p10_up_tp, p10_dn_tp);
    print_row("P50 ", p50_up, p50_dn, p50_fbl, p50_up_tp, p50_dn_tp);
    print_row("P90 ", p90_up, p90_dn, p90_fbl, p90_up_tp, p90_dn_tp);
    print_row("P100", p100_up, p100_dn, p100_fbl, p100_up_tp, p100_dn_tp);
    println!();
}

fn print_row(label: &str, upload_ns: u64, download_ns: u64, fbl_ns: u64, up_tp: f64, dn_tp: f64) {
    let ul = format_duration_ns(upload_ns);
    let dl = format_duration_ns(download_ns);
    let fbl = format_duration_ns(fbl_ns);
    let utp = format!("{:.2} Mb/s", up_tp);
