fn main() {
    let args: Vec<String> = std::env::args().collect();
    let prog = args[0].clone();

    if args.len() < 2 {
        print_main_help(&prog);
        std::process::exit(2);
    }

    match args[1].as_str() {
        "server" => {
            let opts = parse_server_opts(&prog, &args[2..]);
            run_server(opts);
        }
        "client" => {
            let opts = parse_client_opts(&prog, &args[2..]);
            run_client(opts);
        }
        "help" => {
            if args.len() > 2 {
                match args[2].as_str() {
                    "server" => print_server_help(&prog, true),
                    "client" => print_client_help(&prog, true),
                    _ => print_main_help(&prog),
                }
            } else {
                print_main_help(&prog);
            }
        }
        "-h" | "--help" => {
            print_main_help(&prog);
        }
        arg => {
            eprintln!("error: unexpected argument '{}' found\n\nUsage: {} <COMMAND>\n\nFor more information, try '--help'.", arg, prog);
            std::process::exit(2);
        }
    }
}

fn print_main_help(prog: &str) {
    println!("Usage: {prog} <COMMAND>

Commands:
  server  Run as a perf server
  client  Run as a perf client
  help    Print this message or the help of the given subcommand(s)

Options:
  -h, --help  Print help");
}

fn arg_missing(flag: &str, prog: &str) -> ! {
    eprintln!("error: a value is required for '{}' but none was supplied\n\nFor more information, try '--help'.", flag);
    std::process::exit(2);
}
