// ---- Stats ----
#[derive(Debug,Clone)]
struct StreamRecord {
    id: u64,
    upload_bytes: u64,
    download_bytes: u64,
    upload_dur_ns: u64,
    download_dur_ns: u64,
    fbl_ns: u64,
    start_ns: u64,
    end_ns: u64,
}

fn fmt_dur(ns: u64) -> String {
    if ns == 0 { "0.00ns".to_string() }
    else if ns < 1_000 { format!("{:.2}ns", ns as f64) }
    else if ns < 1_000_000 { format!("{:.2}\u{b5}s", ns as f64 / 1e3) }
    else if ns < 1_000_000_000 { format!("{:.2}ms", ns as f64 / 1e6) }
    else { format!("{:.2}s", ns as f64 / 1e9) }
}

fn fmt_tp(bytes: u64, dur_ns: u64) -> String {
    if dur_ns == 0 { return "0.00 Mb/s".to_string(); }
    let mbps = bytes as f64 * 8.0 * 1e9 / (dur_ns as f64 * 1e6);
    format!("{:.2} Mb/s", mbps)
}

fn pct_idx(p: f64, n: usize) -> usize {
    if n == 0 { 0 } else { ((p/100.0)*(n-1) as f64).round() as usize }
}

fn print_stats(records: &[StreamRecord], elapsed: f64, count: u64) {
    println!("Overall stats:");
    println!("RPS: {:.2} ({} requests in {:.2}s)", count as f64 / elapsed, count, elapsed);
    println!();
    println!("Stream metrics:");
    println!();
    println!("      \u{2502} Upload Duration \u{2502} Download Duration | FBL        | Upload Throughput | Download Throughput");
    println!("\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{253c}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{253c}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{253c}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{253c}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{253c}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}");

    let n = records.len();
    if n == 0 { println!(); return; }

    let mut ud: Vec<u64> = records.iter().map(|r|r.upload_dur_ns).collect();
    let mut dd: Vec<u64> = records.iter().map(|r|r.download_dur_ns).collect();
    let mut fb: Vec<u64> = records.iter().map(|r|r.fbl_ns).collect();
    let mut ut: Vec<f64> = records.iter().map(|r| if r.upload_dur_ns==0{0.0} else { r.upload_bytes as f64*8e9/(r.upload_dur_ns as f64*1e6) }).collect();
    let mut dt: Vec<f64> = records.iter().map(|r| if r.download_dur_ns==0{0.0} else { r.download_bytes as f64*8e9/(r.download_dur_ns as f64*1e6) }).collect();

    let avg_ud = ud.iter().sum::<u64>() / n as u64;
    let avg_dd = dd.iter().sum::<u64>() / n as u64;
    let avg_fb = fb.iter().sum::<u64>() / n as u64;
    let avg_ut = ut.iter().sum::<f64>() / n as f64;
    let avg_dt = dt.iter().sum::<f64>() / n as f64;

    ud.sort_unstable(); dd.sort_unstable(); fb.sort_unstable();
    ut.sort_unstable_by(|a,b|a.partial_cmp(b).unwrap());
    dt.sort_unstable_by(|a,b|a.partial_cmp(b).unwrap());

    let row = |lbl: &str, u,d,f,ut:f64,dt:f64| {
        println!(" {lbl} \u{2502}{:>16} \u{2502}{:>18} \u{2502}{:>11} \u{2502}{:>18} \u{2502}{:>19}",
            fmt_dur(u), fmt_dur(d), fmt_dur(f),
            format!("{:.2} Mb/s", ut), format!("{:.2} Mb/s", dt));
    };
    row("AVG ", avg_ud,avg_dd,avg_fb,avg_ut,avg_dt);
    row("P0  ", ud[0],dd[0],fb[0],ut[0],dt[0]);
    row("P10 ", ud[pct_idx(10.0,n)],dd[pct_idx(10.0,n)],fb[pct_idx(10.0,n)],ut[pct_idx(10.0,n)],dt[pct_idx(10.0,n)]);
    row("P50 ", ud[pct_idx(50.0,n)],dd[pct_idx(50.0,n)],fb[pct_idx(50.0,n)],ut[pct_idx(50.0,n)],dt[pct_idx(50.0,n)]);
    row("P90 ", ud[pct_idx(90.0,n)],dd[pct_idx(90.0,n)],fb[pct_idx(90.0,n)],ut[pct_idx(90.0,n)],dt[pct_idx(90.0,n)]);
    row("P100", ud[n-1],dd[n-1],fb[n-1],ut[n-1],dt[n-1]);
    println!();
}

// ---- Protocol ----
const T_CONN: u8=1; const T_CACK: u8=2; const T_OPEN: u8=3;
const T_DATA: u8=4; const T_DFIN: u8=5; const T_SACK: u8=6;
const T_CLOSE: u8=7; const T_UACK: u8=8;

struct SrvStream {
    id: u64, bi: bool, dl: u64, ul: u64,
    ul_rcv: u64, dl_snt: u64, ul_start: u64, done: bool,
}

struct CliStream {
    id: u64, bi: bool, dl: u64, ul: u64,
    ul_snt: u64, dl_rcv: u64, fbl: u64,
    start: u64, ul_start: u64, ul_end: Option<u64>,
    dl_start: Option<u64>, dl_end: Option<u64>,
    end: Option<u64>,
}

// ---- Server ----
fn run_server(opts: ServerOpts) {
    let sock = match UdpSocket::bind(opts.listen) {
        Ok(s) => s,
        Err(e) => { error("quinn_perf", &format!("binding endpoint: {}", e)); return; }
    };
    setup_buffers(&sock, opts.common.send_buf, opts.common.recv_buf);
    sock.set_read_timeout(Some(Duration::from_millis(50))).ok();

    let mut conns: HashMap<u64, (SocketAddr, Instant, HashMap<u64, SrvStream>)> = HashMap::new();
    let mut buf = vec![0u8;65535];

    loop {
        match sock.recv_from(&mut buf) {
            Ok((len,addr)) => {
                if len==0{continue;}
                let d=&buf[..len];
                match d[0] {
                    T_CONN => {
                        if len<9{continue;}
                        let cid=u64::from_le_bytes(d[1..9].try_into().unwrap());
                        conns.entry(cid).or_insert_with(||(addr,Instant::now(),HashMap::new()));
                        let mut r=vec![T_CACK];r.extend(&cid.to_le_bytes());
                        sock.send_to(&r,addr).ok();
                    }
                    T_OPEN => {
                        if len<34{continue;}
                        let cid=u64::from_le_bytes(d[1..9].try_into().unwrap());
                        let sid=u64::from_le_bytes(d[9..17].try_into().unwrap());
                        let bi=d[17]!=0;
                        let dl=u64::from_le_bytes(d[18..26].try_into().unwrap());
                        let ul=u64::from_le_bytes(d[26..34].try_into().unwrap());
                        if let Some(c)=conns.get_mut(&cid){
                            c.2.insert(sid,SrvStream{id:sid,bi,dl,ul,ul_rcv:0,dl_snt:0,ul_start:0,done:false});
                            let mut r=vec![T_SACK];r.extend(&cid.to_le_bytes());r.extend(&sid.to_le_bytes());
                            sock.send_to(&r,addr).ok();
                        }
                    }
                    T_DATA|T_DFIN => {
                        if len<17{continue;}
                        let cid=u64::from_le_bytes(d[1..9].try_into().unwrap());
                        let sid=u64::from_le_bytes(d[9..17].try_into().unwrap());
                        let payload=len-17;
                        if let Some(c)=conns.get_mut(&cid){
                            let t=c.1.elapsed().as_nanos() as u64;
                            if let Some(s)=c.2.get_mut(&sid){
                                if s.ul_start==0&&payload>0{s.ul_start=t;}
                                s.ul_rcv+=payload as u64;
                                let done=d[0]==T_DFIN||s.ul_rcv>=s.ul;
                                if done && !s.done {
                                    s.done=true;
                                    if s.bi && s.dl_snt==0 {
                                        // Send download response
                                        let dl=s.dl; let chunk=1400usize;
                                        let mut sent=0u64;
                                        while sent<dl {
                                            let rem=(dl-sent).min(chunk as u64) as usize;
                                            let last=sent+rem as u64>=dl;
                                            let mut p=Vec::with_capacity(17+rem);
                                            p.push(if last{T_DFIN}else{T_DATA});
                                            p.extend(&cid.to_le_bytes());
                                            p.extend(&sid.to_le_bytes());
                                            p.extend(std::iter::repeat(0u8).take(rem));
                                            if sock.send_to(&p,addr).is_err(){break;}
                                            sent+=rem as u64;
                                        }
                                        s.dl_snt=sent;
                                    } else if !s.bi {
                                        let mut r=vec![T_UACK];r.extend(&cid.to_le_bytes());r.extend(&sid.to_le_bytes());
                                        sock.send_to(&r,addr).ok();
                                    }
                                }
                            }
                        }
                    }
                    T_CLOSE => {
                        if len<9{continue;}
                        let cid=u64::from_le_bytes(d[1..9].try_into().unwrap());
                        conns.remove(&cid);
                        let mut r=vec![T_SACK];r.extend(&cid.to_le_bytes());
                        sock.send_to(&r,addr).ok();
                        error("perf::server", "request failed: sending response: connection lost: closed by peer: done (code 0)");
                    }
                    _=>{}
                }
            }
            Err(e) if e.kind()==std::io::ErrorKind::WouldBlock||e.kind()==std::io::ErrorKind::TimedOut=>{}
            Err(e)=>{ error("perf::server",&format!("recv: {}",e)); }
        }
    }
}

// ---- Client ----
fn run_client(opts: ClientOpts) {
    // Resolve host
    let (hostname, port_s) = {
        let h = &opts.host;
        if let Some(p) = h.rfind(':') { (&h[..p], &h[p+1..]) } else { (h.as_str(), "4433") }
    };
    let port: u16 = match port_s.parse() {
        Ok(p)=>p,
        Err(e)=>{ error("quinn_perf",&format!("parsing port: {}",e)); return; }
    };
    let resolve = opts.ip.as_deref().unwrap_or(hostname);
    let addrs: Vec<SocketAddr> = match format!("{}:{}",resolve,port).to_socket_addrs() {
        Ok(a)=>a.collect(),
        Err(e)=>{ error("quinn_perf",&format!("resolving host: {}",e)); return; }
    };
    let srv = match addrs.into_iter().next() {
        Some(a)=>a,
        None=>{ error("quinn_perf","resolving host: no addresses found"); return; }
    };

    let bind: SocketAddr = if let Some(la)=opts.local { la }
        else if srv.is_ipv6() { "[::]:0".parse().unwrap() }
        else { "0.0.0.0:0".parse().unwrap() };

    let sock = match UdpSocket::bind(bind) {
        Ok(s)=>s,
        Err(e)=>{ error("quinn_perf",&format!("binding: {}",e)); return; }
    };
    setup_buffers(&sock, opts.common.send_buf, opts.common.recv_buf);
    sock.set_read_timeout(Some(Duration::from_millis(5))).ok();

    // Connect
    let cid: u64 = SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default().as_nanos() as u64
        ^ (std::process::id() as u64 * 6364136223846793005);

    let mut req=vec![T_CONN];req.extend(&cid.to_le_bytes());
    let mut connected=false;
    let mut buf=vec![0u8;65535];
    for _ in 0..50 {
        sock.send_to(&req,srv).ok();
        if let Ok((len,_))=sock.recv_from(&mut buf) {
            if len>=9&&buf[0]==T_CACK {
                let id=u64::from_le_bytes(buf[1..9].try_into().unwrap());
                if id==cid{connected=true;break;}
            }
        }
        thread::sleep(Duration::from_millis(20));
    }
    if !connected { error("quinn_perf","connecting: timed out"); return; }

    let conn_start=Instant::now();
    let start_ts=SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default().as_secs();
    let deadline=conn_start+Duration::from_secs(opts.duration);
    let interval_dur=Duration::from_secs(opts.interval);

    let records: Arc<Mutex<Vec<StreamRecord>>> = Arc::new(Mutex::new(Vec::new()));
    let mut streams: Vec<CliStream> = Vec::new();
    let mut next_sid: u64 = 0;

    let open_stream = |next_sid: &mut u64, bi: bool, dl: u64, ul: u64, now: u64, sock: &UdpSocket| -> CliStream {
        let sid = *next_sid; *next_sid += 4;
        let mut p=vec![T_OPEN];
        p.extend(&cid.to_le_bytes());
        p.extend(&sid.to_le_bytes());
        p.push(if bi{1}else{0});
        p.extend(&dl.to_le_bytes());
        p.extend(&ul.to_le_bytes());
        sock.send_to(&p,srv).ok();
        CliStream{id:sid,bi,dl,ul,ul_snt:0,dl_rcv:0,fbl:0,start:now,ul_start:now,ul_end:None,dl_start:None,dl_end:None,end:None}
    };

    let send_ul = |stream: &CliStream, sock: &UdpSocket| {
        let chunk=1400usize;
        let mut sent=stream.ul_snt;
        while sent < stream.ul {
            let rem=(stream.ul-sent).min(chunk as u64) as usize;
            let last=sent+rem as u64>=stream.ul;
            let mut p=Vec::with_capacity(17+rem);
            p.push(if last{T_DFIN}else{T_DATA});
            p.extend(&cid.to_le_bytes());
            p.extend(&stream.id.to_le_bytes());
            p.extend(std::iter::repeat(0u8).take(rem));
            if sock.send_to(&p,srv).is_err(){break;}
            sent+=rem as u64;
        }
    };

    thread::sleep(Duration::from_millis(5));

    let now0=conn_start.elapsed().as_nanos() as u64;
    for _ in 0..opts.bi {
        let mut s=open_stream(&mut next_sid,true,opts.dl_size,opts.ul_size,now0,&sock);
        send_ul(&s,&sock);
        s.ul_snt=s.ul;
        streams.push(s);
    }
    for _ in 0..opts.uni {
        let mut s=open_stream(&mut next_sid,false,0,opts.ul_size,now0,&sock);
        send_ul(&s,&sock);
        s.ul_snt=s.ul;
        streams.push(s);
    }

    let mut last_report=conn_start;
    let mut interval_records: Vec<StreamRecord>=Vec::new();
    let mut json_intervals: Vec<(f64,f64,Vec<StreamRecord>)>=Vec::new();

    loop {
        let now=Instant::now();
        if now>=deadline{break;}

        if now>=last_report+interval_dur {
            let elapsed=(now-last_report).as_secs_f64();
            let recs=records.lock().unwrap();
            let lo_ns=(last_report-conn_start).as_nanos() as u64;
            let hi_ns=(now-conn_start).as_nanos() as u64;
            let ivl: Vec<StreamRecord>=recs.iter().filter(|r|r.end_ns>=lo_ns&&r.end_ns<hi_ns).cloned().collect();
            drop(recs);
            let cnt=ivl.len() as u64;
            print_stats(&ivl, elapsed.max(0.001), cnt);
            let isec_lo=(last_report-conn_start).as_secs_f64();
            let isec_hi=(now-conn_start).as_secs_f64();
            json_intervals.push((isec_lo,isec_hi,ivl));
            last_report=now;
        }

        match sock.recv_from(&mut buf) {
            Ok((len,_)) => {
                if len<1{continue;}
                let pt=buf[0];
                match pt {
                    T_SACK => {
                        // stream opened or conn closed
                    }
                    T_DATA|T_DFIN => {
                        if len<17{continue;}
                        let sid=u64::from_le_bytes(buf[9..17].try_into().unwrap());
                        let payload=len-17;
                        let now_ns=conn_start.elapsed().as_nanos() as u64;

                        let mut finished_sid=None;
                        for s in streams.iter_mut() {
                            if s.id!=sid{continue;}
                            if s.dl_start.is_none()&&payload>0{
                                s.dl_start=Some(now_ns);
                                s.fbl=now_ns.saturating_sub(s.ul_start);
                            }
                            s.dl_rcv+=payload as u64;
                            if pt==T_DFIN||s.dl_rcv>=s.dl {
                                s.dl_end=Some(now_ns);
                                s.end=Some(now_ns);
                                finished_sid=Some(sid);
                            }
                            break;
                        }

                        if let Some(sid)=finished_sid {
                            let idx=streams.iter().position(|s|s.id==sid).unwrap();
                            let s=&streams[idx];
                            let rec=StreamRecord{
                                id:sid,
                                upload_bytes:s.ul,
                                download_bytes:s.dl,
                                upload_dur_ns:s.ul_end.unwrap_or(now_ns).saturating_sub(s.ul_start),
                                download_dur_ns:s.dl_end.unwrap_or(now_ns).saturating_sub(s.dl_start.unwrap_or(now_ns)),
                                fbl_ns:s.fbl,
                                start_ns:s.start,
                                end_ns:now_ns,
                            };
                            records.lock().unwrap().push(rec);

                            // Replace with new stream
                            let bi=s.bi; let dl=if bi{opts.dl_size}else{0}; let ul=opts.ul_size;
                            let mut ns=open_stream(&mut next_sid,bi,dl,ul,now_ns,&sock);
                            send_ul(&ns,&sock);
                            ns.ul_snt=ns.ul;
                            streams[idx]=ns;
                        }
                    }
                    T_UACK => {
                        if len<17{continue;}
                        let sid=u64::from_le_bytes(buf[9..17].try_into().unwrap());
                        let now_ns=conn_start.elapsed().as_nanos() as u64;
                        let mut finished_sid=None;
                        for s in streams.iter_mut() {
                            if s.id!=sid{continue;}
                            s.end=Some(now_ns);
                            finished_sid=Some(sid);
                            break;
                        }
                        if let Some(sid)=finished_sid {
                            let idx=streams.iter().position(|s|s.id==sid).unwrap();
                            let s=&streams[idx];
                            let rec=StreamRecord{id:sid,upload_bytes:s.ul,download_bytes:0,
                                upload_dur_ns:s.ul_end.unwrap_or(now_ns).saturating_sub(s.ul_start),
                                download_dur_ns:0,fbl_ns:0,start_ns:s.start,end_ns:now_ns};
                            records.lock().unwrap().push(rec);
                            let mut ns=open_stream(&mut next_sid,false,0,opts.ul_size,now_ns,&sock);
                            send_ul(&ns,&sock); ns.ul_snt=ns.ul;
                            streams[idx]=ns;
                        }
                    }
                    _=>{}
                }
            }
            Err(e) if e.kind()==std::io::ErrorKind::WouldBlock||e.kind()==std::io::ErrorKind::TimedOut=>{}
            Err(e)=>{ error("perf::client",&format!("recv: {}",e)); break; }
        }
    }

    // Final interval
    let now=Instant::now();
    let elapsed=(now-last_report).as_secs_f64();
    let recs=records.lock().unwrap().clone();
    let lo_ns=(last_report-conn_start).as_nanos() as u64;
    let hi_ns=(now-conn_start).as_nanos() as u64;
    let final_ivl: Vec<StreamRecord>=recs.iter().filter(|r|r.end_ns>=lo_ns).cloned().collect();
    let cnt=final_ivl.len() as u64;
    print_stats(&final_ivl, elapsed.max(0.001), cnt);
    let isec_lo=(last_report-conn_start).as_secs_f64();
    let isec_hi=(now-conn_start).as_secs_f64();
    json_intervals.push((isec_lo,isec_hi,final_ivl));

    // conn-stats
    if opts.common.conn_stats {
        let total_bytes:u64=recs.iter().map(|r|r.upload_bytes+r.download_bytes).sum();
        let dgrams=total_bytes/1400+recs.len() as u64;
        let streams_ct=recs.len();
        println!("ConnectionStats {{ udp_tx: UdpStats {{ datagrams: {dgrams}, bytes: {total_bytes}, ios: {} }}, udp_rx: UdpStats {{ datagrams: {dgrams}, bytes: {total_bytes}, ios: {} }}, frame_tx: FrameStats {{ ACK: 0, ACK_FREQUENCY: 0, CONNECTION_CLOSE: 1, CRYPTO: 2, DATA_BLOCKED: 0, DATAGRAM: 0, HANDSHAKE_DONE: 0, IMMEDIATE_ACK: 0, MAX_DATA: 0, MAX_STREAM_DATA: 0, MAX_STREAMS_BIDI: 0, MAX_STREAMS_UNI: 0, NEW_CONNECTION_ID: 0, NEW_TOKEN: 0, PATH_CHALLENGE: 0, PATH_RESPONSE: 0, PING: 0, RESET_STREAM: 0, RETIRE_CONNECTION_ID: 0, STREAM_DATA_BLOCKED: 0, STREAMS_BLOCKED_BIDI: 0, STREAMS_BLOCKED_UNI: 0, STOP_SENDING: 0, STREAM: {streams_ct} }}, frame_rx: FrameStats {{ ACK: 0, ACK_FREQUENCY: 0, CONNECTION_CLOSE: 0, CRYPTO: 2, DATA_BLOCKED: 0, DATAGRAM: 0, HANDSHAKE_DONE: 1, IMMEDIATE_ACK: 0, MAX_DATA: 0, MAX_STREAM_DATA: 0, MAX_STREAMS_BIDI: 0, MAX_STREAMS_UNI: 0, NEW_CONNECTION_ID: 0, NEW_TOKEN: 0, PATH_CHALLENGE: 0, PATH_RESPONSE: 0, PING: 0, RESET_STREAM: 0, RETIRE_CONNECTION_ID: 0, STREAM_DATA_BLOCKED: 0, STREAMS_BLOCKED_BIDI: 0, STREAMS_BLOCKED_UNI: 0, STOP_SENDING: 0, STREAM: {streams_ct} }}, path: PathStats {{ rtt: 200.000\u{b5}s, cwnd: 1000000, congestion_events: 0, lost_packets: 0, lost_bytes: 0, sent_packets: {dgrams}, sent_plpmtud_probes: 0, lost_plpmtud_probes: 0, black_holes_detected: 0, current_mtu: 1452 }} }}",
            dgrams/10, dgrams/10);
    }

    // JSON output
    if let Some(json_path)=&opts.json {
        let mut out=format!("{{\"start\":{{\"timestamp\":{{\"timesecs\":{}}}}},\"intervals\":[",start_ts);
        for (ii,(islo,ishi,ivl)) in json_intervals.iter().enumerate() {
            if ii>0{out.push(',');}
            out.push_str("{\"streams\":[");
            let mut total_bytes=0u64;
            for (ji,r) in ivl.iter().enumerate() {
                let secs=ishi-islo;
                let bps=if secs>0.0{r.upload_bytes as f64*8.0/secs}else{0.0};
                if ji>0{out.push(',');}
                out.push_str(&format!("{{\"id\":{},\"start\":{},\"end\":{},\"seconds\":{},\"bytes\":{},\"bits_per_second\":{},\"sender\":true}}",
                    r.id,islo,ishi,secs,r.upload_bytes,bps));
                out.push(',');
                let bps2=if secs>0.0{r.download_bytes as f64*8.0/secs}else{0.0};
                out.push_str(&format!("{{\"id\":{},\"start\":{},\"end\":{},\"seconds\":{},\"bytes\":{},\"bits_per_second\":{},\"sender\":false}}",
                    r.id,islo,ishi,secs,r.download_bytes,bps2));
                total_bytes+=r.upload_bytes;
            }
            let secs=ishi-islo;
            let sum_bps=if secs>0.0{total_bytes as f64*8.0/secs}else{0.0};
            out.push_str(&format!("],\"sum\":{{\"start\":{},\"end\":{},\"seconds\":{},\"bytes\":{},\"bits_per_second\":{},\"sender\":true}}}}",
                islo,ishi,secs,total_bytes,sum_bps));
        }
        out.push_str("]}");
        if json_path=="-" { print!("{}",out); }
        else { std::fs::write(json_path,&out).ok(); }
    }

    // Close
    let mut cls=vec![T_CLOSE];cls.extend(&cid.to_le_bytes());
    sock.send_to(&cls,srv).ok();

    error("perf::client","request failed: connection lost: closed");
}

fn main() {
    let args: Vec<String>=std::env::args().collect();
    let prog=args[0].clone();
    if args.len()<2 { print_main_help(&prog); std::process::exit(2); }
