fn parse_size(s: &str) -> Result<u64, String> {
    if s.ends_with('M') { s[..s.len()-1].parse::<u64>().map(|n|n*1024*1024).map_err(|e|e.to_string()) }
    else if s.ends_with('G') { s[..s.len()-1].parse::<u64>().map(|n|n*1024*1024*1024).map_err(|e|e.to_string()) }
