extern "C" {
    fn setsockopt(sockfd: i32, level: i32, optname: i32, optval: *const c_void, optlen: u32) -> i32;
    fn getsockopt(sockfd: i32, level: i32, optname: i32, optval: *mut c_void, optlen: *mut u32) -> i32;
}

const SOL_SOCKET: i32 = 1;
const SO_SNDBUF: i32 = 7;
const SO_RCVBUF: i32 = 8;

fn set_sock_int(fd: i32, level: i32, opt: i32, val: i32) {
    unsafe { setsockopt(fd, level, opt, &val as *const i32 as *const c_void, 4); }
}
fn get_sock_int(fd: i32, level: i32, opt: i32) -> i32 {
    unsafe {
        let mut v: i32 = 0; let mut l: u32 = 4;
        getsockopt(fd, level, opt, &mut v as *mut i32 as *mut c_void, &mut l);
        v
    }
}

// ---- Logging ----
fn log_ts() -> String {
    let now = SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default();
    let s = now.as_secs(); let us = now.subsec_micros();
    let (yr,mo,dy,h,mi,se) = unix_dt(s);
    format!("{:04}-{:02}-{:02}T{:02}:{:02}:{:02}.{:06}Z",yr,mo,dy,h,mi,se,us)
}
fn unix_dt(s: u64) -> (u32,u32,u32,u32,u32,u32) {
    let tod = (s % 86400) as u32;
    let days = s / 86400;
    let h = tod/3600; let mi = (tod%3600)/60; let se = tod%60;
    let mut yr = 1970u32; let mut d = days;
    loop { let diy = if leap(yr){366u64}else{365u64}; if d<diy{break;} d-=diy; yr+=1; }
    let mons = [31u64,if leap(yr){29}else{28},31,30,31,30,31,31,30,31,30,31];
    let mut mo = 1u32;
    for &m in &mons { if d<m{break;} d-=m; mo+=1; }
    (yr,mo,d as u32+1,h,mi,se)
}
fn leap(y: u32) -> bool { (y%4==0 && y%100!=0) || y%400==0 }
fn warn(module: &str, msg: &str) {
    println!("\x1b[2m{}\x1b[0m \x1b[33m WARN\x1b[0m \x1b[2m{}\x1b[0m\x1b[2m:\x1b[0m {}", log_ts(), module, msg);
}
fn error(module: &str, msg: &str) {
    println!("\x1b[2m{}\x1b[0m \x1b[31mERROR\x1b[0m \x1b[2m{}\x1b[0m\x1b[2m:\x1b[0m {}", log_ts(), module, msg);
}

// ---- Socket buffers ----
use std::os::unix::io::AsRawFd;
fn setup_buffers(sock: &UdpSocket, snd: u64, rcv: u64) {
    let fd = sock.as_raw_fd();
    set_sock_int(fd, SOL_SOCKET, SO_SNDBUF, snd as i32);
    let asnd = get_sock_int(fd, SOL_SOCKET, SO_SNDBUF);
    if asnd < snd as i32 {
        warn("perf", &format!("Unable to set desired send buffer size. Desired: {}, Actual: {}", snd, asnd));
    }
    set_sock_int(fd, SOL_SOCKET, SO_RCVBUF, rcv as i32);
    let arcv = get_sock_int(fd, SOL_SOCKET, SO_RCVBUF);
    if arcv < rcv as i32 {
        warn("perf", &format!("Unable to set desired recv buffer size. Desired: {}, Actual: {}", rcv, arcv));
    }
}

// ---- SI parsing ----
fn parse_size(s: &str) -> Result<u64, String> {
    if s.ends_with('M') { s[..s.len()-1].parse::<u64>().map(|n|n*1024*1024).map_err(|e|e.to_string()) }
    else if s.ends_with('G') { s[..s.len()-1].parse::<u64>().map(|n|n*1024*1024*1024).map_err(|e|e.to_string()) }
    else { s.parse::<u64>().map_err(|e|e.to_string()) }
}

