fn parse_server(prog: &str, args: &[String]) -> ServerOpts {
    for a in args { if a=="-h"{print_server_help(prog,false);std::process::exit(0);} if a=="--help"{print_server_help(prog,true);std::process::exit(0);} }
    let (common, rest) = parse_common(args, prog);
    let mut listen_s = "[::]:4433".to_string();
    let mut key = None; let mut cert = None;
    let mut i = 0;
    while i < rest.len() {
        match rest[i].as_str() {
            "--listen" => { i+=1; if i>=rest.len(){die("error: a value is required for '--listen' but none was supplied\n\nFor more information, try '--help'.".into());}; listen_s=rest[i].clone(); }
            "-k"|"--key" => { i+=1; if i>=rest.len(){die("error: a value is required for '--key' but none was supplied\n\nFor more information, try '--help'.".into());}; key=Some(rest[i].clone()); }
            "-c"|"--cert" => { i+=1; if i>=rest.len(){die("error: a value is required for '--cert' but none was supplied\n\nFor more information, try '--help'.".into());}; cert=Some(rest[i].clone()); }
            a if a.starts_with('-') => die(&format!("error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\nUsage: {} server [OPTIONS]\n\nFor more information, try '--help'.",a,a,a,prog)),
            a => die(&format!("error: unexpected argument '{}' found\n\nUsage: {} server [OPTIONS]\n\nFor more information, try '--help'.",a,prog)),
        }
        i+=1;
    }
    let listen: SocketAddr = listen_s.parse().unwrap_or_else(|_| die(&format!("error: invalid value '{}' for '--listen <LISTEN>': invalid socket address syntax\n\nFor more information, try '--help'.",listen_s)));
    ServerOpts { listen, key, cert, common }
}

fn parse_client(prog: &str, args: &[String]) -> ClientOpts {
    for a in args { if a=="-h"{print_client_help(prog,false);std::process::exit(0);} if a=="--help"{print_client_help(prog,true);std::process::exit(0);} }
    let (common, rest) = parse_common(args, prog);
    let mut host="localhost:4433".to_string(); let mut ip=None; let mut local=None;
    let mut uni=0u64; let mut bi=1u64; let mut dl=1024*1024u64; let mut ul=1024*1024u64;
    let mut dur=60u64; let mut intv=1u64; let mut json=None;
    let mut pos=false;
    let mut i=0;
    while i<rest.len() {
        match rest[i].as_str() {
            "--ip" => { i+=1; ip=Some(nv(&rest,i,prog,"--ip")); }
            "--local-addr" => { i+=1; let v=nv(&rest,i,prog,"--local-addr"); local=Some(v.parse::<SocketAddr>().unwrap_or_else(|_|die(&format!("error: invalid value '{}' for '--local-addr <LOCAL_ADDR>': invalid socket address syntax\n\nFor more information, try '--help'.",v)))); }
            "--uni-requests" => { i+=1; let v=nv(&rest,i,prog,"--uni-requests"); uni=pu64(&v,prog,"--uni-requests","UNI_REQUESTS"); }
            "--bi-requests" => { i+=1; let v=nv(&rest,i,prog,"--bi-requests"); bi=pu64(&v,prog,"--bi-requests","BI_REQUESTS"); }
            "--download-size" => { i+=1; let v=nv(&rest,i,prog,"--download-size"); dl=psz(&v,prog,"--download-size","DOWNLOAD_SIZE"); }
            "--upload-size" => { i+=1; let v=nv(&rest,i,prog,"--upload-size"); ul=psz(&v,prog,"--upload-size","UPLOAD_SIZE"); }
            "--duration" => { i+=1; let v=nv(&rest,i,prog,"--duration"); dur=pu64(&v,prog,"--duration","DURATION"); }
            "--interval" => { i+=1; let v=nv(&rest,i,prog,"--interval"); intv=pu64(&v,prog,"--interval","INTERVAL"); }
            "--json" => { i+=1; json=Some(nv(&rest,i,prog,"--json")); }
            a if a.starts_with('-') => die(&format!("error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\nUsage: {} client [OPTIONS] [HOST]\n\nFor more information, try '--help'.",a,a,a,prog)),
            a => { if pos{die(&format!("error: unexpected argument '{}' found\n\nUsage: {} client [OPTIONS] [HOST]\n\nFor more information, try '--help'.",a,prog));} host=a.to_string(); pos=true; }
        }
        i+=1;
    }
    ClientOpts { host, ip, local, uni, bi, dl_size:dl, ul_size:ul, duration:dur, interval:intv, json, common }
}

