use std::ffi::c_void;
use std::net::{SocketAddr, UdpSocket, ToSocketAddrs};
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant, SystemTime, UNIX_EPOCH};
use std::thread;
use std::collections::HashMap;

extern "C" {
    fn setsockopt(sockfd: i32, level: i32, optname: i32, optval: *const c_void, optlen: u32) -> i32;
    fn getsockopt(sockfd: i32, level: i32, optname: i32, optval: *mut c_void, optlen: *mut u32) -> i32;
}

const SOL_SOCKET: i32 = 1;
const SO_SNDBUF: i32 = 7;
const SO_RCVBUF: i32 = 8;

fn set_sock_int(fd: i32, level: i32, opt: i32, val: i32) {
    unsafe { setsockopt(fd, level, opt, &val as *const i32 as *const c_void, 4); }
}
fn get_sock_int(fd: i32, level: i32, opt: i32) -> i32 {
    unsafe {
        let mut v: i32 = 0; let mut l: u32 = 4;
        getsockopt(fd, level, opt, &mut v as *mut i32 as *mut c_void, &mut l);
        v
    }
}

// ---- Logging ----
fn log_ts() -> String {
    let now = SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default();
    let s = now.as_secs(); let us = now.subsec_micros();
    let (yr,mo,dy,h,mi,se) = unix_dt(s);
    format!("{:04}-{:02}-{:02}T{:02}:{:02}:{:02}.{:06}Z",yr,mo,dy,h,mi,se,us)
}
fn unix_dt(s: u64) -> (u32,u32,u32,u32,u32,u32) {
    let tod = (s % 86400) as u32;
    let days = s / 86400;
    let h = tod/3600; let mi = (tod%3600)/60; let se = tod%60;
    let mut yr = 1970u32; let mut d = days;
    loop { let diy = if leap(yr){366u64}else{365u64}; if d<diy{break;} d-=diy; yr+=1; }
    let mons = [31u64,if leap(yr){29}else{28},31,30,31,30,31,31,30,31,30,31];
    let mut mo = 1u32;
    for &m in &mons { if d<m{break;} d-=m; mo+=1; }
    (yr,mo,d as u32+1,h,mi,se)
}
fn leap(y: u32) -> bool { (y%4==0 && y%100!=0) || y%400==0 }
fn warn(module: &str, msg: &str) {
    println!("\x1b[2m{}\x1b[0m \x1b[33m WARN\x1b[0m \x1b[2m{}\x1b[0m\x1b[2m:\x1b[0m {}", log_ts(), module, msg);
}
fn error(module: &str, msg: &str) {
    println!("\x1b[2m{}\x1b[0m \x1b[31mERROR\x1b[0m \x1b[2m{}\x1b[0m\x1b[2m:\x1b[0m {}", log_ts(), module, msg);
}

// ---- Socket buffers ----
use std::os::unix::io::AsRawFd;
fn setup_buffers(sock: &UdpSocket, snd: u64, rcv: u64) {
    let fd = sock.as_raw_fd();
    set_sock_int(fd, SOL_SOCKET, SO_SNDBUF, snd as i32);
    let asnd = get_sock_int(fd, SOL_SOCKET, SO_SNDBUF);
    if asnd < snd as i32 {
        warn("perf", &format!("Unable to set desired send buffer size. Desired: {}, Actual: {}", snd, asnd));
    }
    set_sock_int(fd, SOL_SOCKET, SO_RCVBUF, rcv as i32);
    let arcv = get_sock_int(fd, SOL_SOCKET, SO_RCVBUF);
    if arcv < rcv as i32 {
        warn("perf", &format!("Unable to set desired recv buffer size. Desired: {}, Actual: {}", rcv, arcv));
    }
}

// ---- SI parsing ----
fn parse_size(s: &str) -> Result<u64, String> {
    if s.ends_with('M') { s[..s.len()-1].parse::<u64>().map(|n|n*1024*1024).map_err(|e|e.to_string()) }
    else if s.ends_with('G') { s[..s.len()-1].parse::<u64>().map(|n|n*1024*1024*1024).map_err(|e|e.to_string()) }
    else { s.parse::<u64>().map_err(|e|e.to_string()) }
}

// ---- Options ----
#[derive(Debug,Clone,Default)]
struct CommonOpts {
    send_buf: u64, recv_buf: u64, conn_stats: bool, keylog: bool,
    initial_mtu: u64, no_protection: bool, initial_rtt: Option<u64>,
    ack_frequency: bool, congestion: Option<String>,
    stream_rcv_win: Option<u64>, rcv_win: Option<u64>, snd_win: Option<u64>,
    max_udp: u64, qlog: Option<String>,
}
impl CommonOpts {
    fn new() -> Self {
        CommonOpts { send_buf: 2*1024*1024, recv_buf: 2*1024*1024,
            initial_mtu: 1200, max_udp: 1472, ..Default::default() }
    }
}
#[derive(Debug,Clone)]
struct ServerOpts { listen: SocketAddr, key: Option<String>, cert: Option<String>, common: CommonOpts }
#[derive(Debug,Clone)]
struct ClientOpts {
    host: String, ip: Option<String>, local: Option<SocketAddr>,
    uni: u64, bi: u64, dl_size: u64, ul_size: u64,
    duration: u64, interval: u64, json: Option<String>, common: CommonOpts,
}

fn die(msg: &str) -> ! { eprintln!("{}", msg); std::process::exit(2); }

fn parse_common(args: &[String], prog: &str) -> (CommonOpts, Vec<String>) {
    let mut o = CommonOpts::new();
    let mut rest = Vec::new();
    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "--send-buffer-size" => { i+=1; let v=nv(args,i,prog,"--send-buffer-size"); o.send_buf=psz(&v,prog,"--send-buffer-size","SEND_BUFFER_SIZE"); }
            "--recv-buffer-size" => { i+=1; let v=nv(args,i,prog,"--recv-buffer-size"); o.recv_buf=psz(&v,prog,"--recv-buffer-size","RECV_BUFFER_SIZE"); }
            "--conn-stats" => { o.conn_stats=true; }
            "--keylog" => { o.keylog=true; }
            "--initial-mtu" => { i+=1; let v=nv(args,i,prog,"--initial-mtu"); o.initial_mtu=pu64(&v,prog,"--initial-mtu","INITIAL_MTU"); }
            "--no-protection" => { o.no_protection=true; }
            "--initial-rtt" => { i+=1; let v=nv(args,i,prog,"--initial-rtt"); o.initial_rtt=Some(pu64(&v,prog,"--initial-rtt","INITIAL_RTT")); }
            "--ack-frequency" => { o.ack_frequency=true; }
            "--congestion" => { i+=1; let v=nv(args,i,prog,"--congestion");
                match v.as_str() { "cubic"|"bbr"|"new-reno" => o.congestion=Some(v.clone()),
                    _ => die(&format!("error: invalid value '{}' for '--congestion <CONG_ALG>'\n  [possible values: cubic, bbr, new-reno]\n\nFor more information, try '--help'.",v)) } }
            "--stream-receive-window" => { i+=1; let v=nv(args,i,prog,"--stream-receive-window"); o.stream_rcv_win=Some(psz(&v,prog,"--stream-receive-window","STREAM_RECEIVE_WINDOW")); }
            "--receive-window" => { i+=1; let v=nv(args,i,prog,"--receive-window"); o.rcv_win=Some(psz(&v,prog,"--receive-window","RECEIVE_WINDOW")); }
            "--send-window" => { i+=1; let v=nv(args,i,prog,"--send-window"); o.snd_win=Some(psz(&v,prog,"--send-window","SEND_WINDOW")); }
            "--max-udp-payload-size" => { i+=1; let v=nv(args,i,prog,"--max-udp-payload-size"); o.max_udp=pu64(&v,prog,"--max-udp-payload-size","MAX_UDP_PAYLOAD_SIZE"); }
            "--qlog" => { i+=1; o.qlog=Some(nv(args,i,prog,"--qlog")); }
            _ => rest.push(args[i].clone()),
        }
        i+=1;
    }
    (o, rest)
}

fn nv(args: &[String], i: usize, prog: &str, flag: &str) -> String {
    if i >= args.len() { die(&format!("error: a value is required for '{}' but none was supplied\n\nFor more information, try '--help'.",flag)); }
    args[i].clone()
}
fn psz(v: &str, prog: &str, flag: &str, meta: &str) -> u64 {
    parse_size(v).unwrap_or_else(|e| die(&format!("error: invalid value '{}' for '{} <{}>': {}\n\nFor more information, try '--help'.",v,flag,meta,e)))
}
fn pu64(v: &str, prog: &str, flag: &str, meta: &str) -> u64 {
    v.parse::<u64>().unwrap_or_else(|e| die(&format!("error: invalid value '{}' for '{} <{}>': {}\n\nFor more information, try '--help'.",v,flag,meta,e)))
}

fn parse_server(prog: &str, args: &[String]) -> ServerOpts {
    for a in args { if a=="-h"{print_server_help(prog,false);std::process::exit(0);} if a=="--help"{print_server_help(prog,true);std::process::exit(0);} }
    let (common, rest) = parse_common(args, prog);
    let mut listen_s = "[::]:4433".to_string();
    let mut key = None; let mut cert = None;
    let mut i = 0;
    while i < rest.len() {
        match rest[i].as_str() {
            "--listen" => { i+=1; if i>=rest.len(){die("error: a value is required for '--listen' but none was supplied\n\nFor more information, try '--help'.".into());}; listen_s=rest[i].clone(); }
            "-k"|"--key" => { i+=1; if i>=rest.len(){die("error: a value is required for '--key' but none was supplied\n\nFor more information, try '--help'.".into());}; key=Some(rest[i].clone()); }
            "-c"|"--cert" => { i+=1; if i>=rest.len(){die("error: a value is required for '--cert' but none was supplied\n\nFor more information, try '--help'.".into());}; cert=Some(rest[i].clone()); }
            a if a.starts_with('-') => die(&format!("error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\nUsage: {} server [OPTIONS]\n\nFor more information, try '--help'.",a,a,a,prog)),
            a => die(&format!("error: unexpected argument '{}' found\n\nUsage: {} server [OPTIONS]\n\nFor more information, try '--help'.",a,prog)),
        }
        i+=1;
    }
    let listen: SocketAddr = listen_s.parse().unwrap_or_else(|_| die(&format!("error: invalid value '{}' for '--listen <LISTEN>': invalid socket address syntax\n\nFor more information, try '--help'.",listen_s)));
    ServerOpts { listen, key, cert, common }
}

fn parse_client(prog: &str, args: &[String]) -> ClientOpts {
    for a in args { if a=="-h"{print_client_help(prog,false);std::process::exit(0);} if a=="--help"{print_client_help(prog,true);std::process::exit(0);} }
    let (common, rest) = parse_common(args, prog);
    let mut host="localhost:4433".to_string(); let mut ip=None; let mut local=None;
    let mut uni=0u64; let mut bi=1u64; let mut dl=1024*1024u64; let mut ul=1024*1024u64;
    let mut dur=60u64; let mut intv=1u64; let mut json=None;
    let mut pos=false;
    let mut i=0;
    while i<rest.len() {
        match rest[i].as_str() {
            "--ip" => { i+=1; ip=Some(nv(&rest,i,prog,"--ip")); }
            "--local-addr" => { i+=1; let v=nv(&rest,i,prog,"--local-addr"); local=Some(v.parse::<SocketAddr>().unwrap_or_else(|_|die(&format!("error: invalid value '{}' for '--local-addr <LOCAL_ADDR>': invalid socket address syntax\n\nFor more information, try '--help'.",v)))); }
            "--uni-requests" => { i+=1; let v=nv(&rest,i,prog,"--uni-requests"); uni=pu64(&v,prog,"--uni-requests","UNI_REQUESTS"); }
            "--bi-requests" => { i+=1; let v=nv(&rest,i,prog,"--bi-requests"); bi=pu64(&v,prog,"--bi-requests","BI_REQUESTS"); }
            "--download-size" => { i+=1; let v=nv(&rest,i,prog,"--download-size"); dl=psz(&v,prog,"--download-size","DOWNLOAD_SIZE"); }
            "--upload-size" => { i+=1; let v=nv(&rest,i,prog,"--upload-size"); ul=psz(&v,prog,"--upload-size","UPLOAD_SIZE"); }
            "--duration" => { i+=1; let v=nv(&rest,i,prog,"--duration"); dur=pu64(&v,prog,"--duration","DURATION"); }
            "--interval" => { i+=1; let v=nv(&rest,i,prog,"--interval"); intv=pu64(&v,prog,"--interval","INTERVAL"); }
            "--json" => { i+=1; json=Some(nv(&rest,i,prog,"--json")); }
            a if a.starts_with('-') => die(&format!("error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\nUsage: {} client [OPTIONS] [HOST]\n\nFor more information, try '--help'.",a,a,a,prog)),
            a => { if pos{die(&format!("error: unexpected argument '{}' found\n\nUsage: {} client [OPTIONS] [HOST]\n\nFor more information, try '--help'.",a,prog));} host=a.to_string(); pos=true; }
        }
        i+=1;
    }
    ClientOpts { host, ip, local, uni, bi, dl_size:dl, ul_size:ul, duration:dur, interval:intv, json, common }
}

