# The server always prints the error on T_CLOSE. Let me fix this to only print
# when there were active streams (i.e., connections with pending streams).

# Actually, looking at the original behavior:
# - The server error "request failed: sending response: connection lost: closed by peer"
#   appears when the server was in the MIDDLE of sending a response when the client closed.
# - This happens because the client has a duration limit and will close the connection
#   even if there are ongoing requests.
# 
# In my implementation, I always print the error, which is wrong.
# 
# Let me fix: check if there were any streams in the connection before printing error.

# Let me use python to make the fix:
python3 << 'EOF'
content = open('/workspace/src/main.rs').read()

old = '''                    T_CLOSE => {
                        if len<9{continue;}
                        let cid=u64::from_le_bytes(d[1..9].try_into().unwrap());
                        conns.remove(&cid);
                        let mut r=vec![T_SACK];r.extend(&cid.to_le_bytes());
                        sock.send_to(&r,addr).ok();
                        error("perf::server", "request failed: sending response: connection lost: closed by peer: done (code 0)");
                    }'''

new = '''                    T_CLOSE => {
                        if len<9{continue;}
                        let cid=u64::from_le_bytes(d[1..9].try_into().unwrap());
                        if let Some(conn) = conns.remove(&cid) {
                            // Check if there were active/incomplete streams
                            let had_active = conn.2.values().any(|s| !s.done);
                            let mut r=vec![T_SACK];r.extend(&cid.to_le_bytes());
                            sock.send_to(&r,addr).ok();
                            if had_active {
                                error("perf::server", "request failed: sending response: connection lost: closed by peer: done (code 0)");
                            }
                        }
                    }'''

content = content.replace(old, new, 1)
open('/workspace/src/main.rs', 'w').write(content)
print("Fixed server error handling")
EOF

